Object.assign(window.__SYN,{"c:弦+虚": {"o": "虚弦脉总以虚为本，以弦为标，主正虚而兼肝旺、木乘、邪恋之候。虚为气血阴阳亏虚，弦为肝郁气滞、肝风内动或痰饮瘀阻。其病机类别虽多，然相互关联：虚则肝失濡养而弦，弦则木旺乘土，土虚又生湿痰，虚火内扰则风动。故临床可见纯虚、虚中夹实、虚极欲脱等不同层次，总属本虚标实、脏腑功能失调之象。", "c": [{"name": "主虚", "desc": "虚弦脉以虚为本，主气血阴阳亏虚。原文多称虚为气弱、阴亏、营血耗损、脾土不足等，如年五十阴气自半、疟久伤脾、产后正阴交伤、气血两亏等，皆见脉虚弦。虚脉示正气不足，弦为兼标，故虚弦首先反映诸虚劳损。"}, {"name": "主肝旺", "desc": "弦为肝脉，虚弦常见肝木偏旺、肝阳上亢、肝风内动。原文有肝阳上升、厥阴内风暗动、木失涵养、水不涵木等，症见眩晕耳鸣、肢麻抽搐、头摇心悸。虚为肝阴血不足，弦为肝旺风动，故主肝旺风动之机。"}, {"name": "主木乘土", "desc": "虚弦脉主土虚木乘、肝脾不和。原文见中气不足而风邪乘脾、脾虚虫积、肝邪侮土腹胀、肝风犯胃食不能下等。虚为脾土虚弱，弦为肝木偏旺，木旺乘土，脾失健运，故见腹痛、泄泻、食少、胀满等症。"}, {"name": "主虚中夹实", "desc": "虚弦脉主正虚邪恋、虚实夹杂。原文有疟邪未净、湿浊不化、痰饮内伏、虫积气滞、余毒留恋等，皆虚弦并见。虚为正虚，弦为邪郁气滞或痰饮内阻，故脉象示本虚标实，不可纯补纯攻。"}, {"name": "主血虚风动", "desc": "虚弦脉主营血亏虚、风阳入络或虚风暗动。原文见血去络空、风阳入络、营血暴亏、风阳上逆、血虚生风等，症见抽搐、眩晕、麻木。虚为血虚不能濡养，弦为肝风内动，故主血虚风动之候。"}, {"name": "主阴虚火旺", "desc": "虚弦脉主阴液亏虚、虚火内扰。原文有肝肾阴虚、虚火载血上行、水亏木旺、相火不静、阴亏肝升等。虚为阴亏，弦为肝火偏旺，火性上炎，故见吐血、咳逆、耳鸣、少寐、舌光等阴虚火旺之象。"}], "n": {"主虚": 12, "主肝旺": 1, "主木乘土": 36, "主虚中夹实": 31, "主血虚风动": 22, "主阴虚火旺": 22}, "a": {"216": "主木乘土", "275": "主木乘土", "326": "主虚中夹实", "406": "主木乘土", "468": "主虚中夹实", "513": "主虚中夹实", "520": "主阴虚火旺", "1125": "主木乘土", "1202": "主木乘土", "1773": "主木乘土", "2271": "主阴虚火旺", "2538": "主阴虚火旺", "2755": "主虚中夹实", "2772": "主木乘土", "2905": "主虚中夹实", "3774": "主虚", "4974": "主木乘土", "6603": "主虚中夹实", "6618": "主血虚风动", "6633": "主阴虚火旺", "6643": "主木乘土", "6670": "主虚中夹实", "6681": "主木乘土", "6687": "主血虚风动", "6690": "主木乘土", "6708": "主木乘土", "6729": "主木乘土", "6749": "主木乘土", "6784": "主木乘土", "6796": "主虚", "6800": "主血虚风动", "6823": "主木乘土", "6855": "主虚", "6920": "主血虚风动", "6971": "主阴虚火旺", "7014": "主血虚风动", "7015": "主血虚风动", "7245": "主血虚风动", "7246": "主血虚风动", "7445": "主木乘土", "7450": "主阴虚火旺", "7451": "主阴虚火旺", "7630": "主虚中夹实", "7663": "主阴虚火旺", "7693": "主血虚风动", "7713": "主虚中夹实", "7756": "主血虚风动", "7769": "主木乘土", "7779": "主木乘土", "7823": "主虚中夹实", "7991": "主血虚风动", "8019": "主肝旺", "8023": "主阴虚火旺", "8078": "主木乘土", "8107": "主血虚风动", "8125": "主血虚风动", "8580": "主木乘土", "8597": "主木乘土", "8942": "主虚中夹实", "9490": "主虚中夹实", "9570": "主阴虚火旺", "9786": "主虚中夹实", "9974": "主阴虚火旺", "10143": "主血虚风动", "10169": "主虚中夹实", "10214": "主木乘土", "10498": "主虚中夹实", "10512": "主木乘土", "10985": "主虚中夹实", "11006": "主木乘土", "11039": "主虚中夹实", "11041": "主木乘土", "11472": "主木乘土", "11535": "主血虚风动", "11536": "主血虚风动", "11538": "主阴虚火旺", "11702": "主木乘土", "11835": "主虚", "11858": "主虚", "11889": "主虚", "12523": "主木乘土", "12712": "主阴虚火旺", "12718": "主阴虚火旺", "12826": "主虚中夹实", "12827": "主虚中夹实", "12837": "主虚", "12893": "主血虚风动", "12899": "主虚", "12903": "主阴虚火旺", "13018": "主虚中夹实", "13242": "主虚中夹实", "13314": "主血虚风动", "13842": "主血虚风动", "14068": "主虚中夹实", "14123": "主虚中夹实", "14136": "主虚中夹实", "14154": "主阴虚火旺", "14172": "主阴虚火旺", "14185": "主阴虚火旺", "14262": "主虚中夹实", "14429": "主虚中夹实", "14561": "主血虚风动", "15454": "主阴虚火旺", "15455": "主木乘土", "15496": "主木乘土", "15542": "主阴虚火旺", "15577": "主虚", "15669": "主木乘土", "15742": "主虚中夹实", "15787": "主虚中夹实", "15869": "主木乘土", "15905": "主阴虚火旺", "15923": "主木乘土", "15983": "主虚", "16051": "主血虚风动", "16492": "主虚中夹实", "16882": "主血虚风动", "16912": "主木乘土", "16943": "主虚", "17141": "主虚中夹实", "17147": "主木乘土", "18494": "主阴虚火旺", "21805": "主虚中夹实", "23337": "主虚"}, "t": 124, "np": 0}, "c:弦+空": {"o": "空弦脉总属虚实夹杂之象，以虚为本，以实为标。空主血虚、阴伤、元气不足，弦主气机郁滞、肝木偏旺或邪气壅结。故其主病机可归纳为：主肝病、主虚损、主虚中夹实、主痰湿、主瘀滞、主肝脾不调。各类之间相互关联：肝病与肝脾不调均以弦为定位，空示中虚；虚损为根本，虚中夹实为总纲；痰湿、瘀滞为标实之变。总以正虚邪恋、气血失和为要，治当扶正祛邪、调肝理脾。", "c": [{"name": "主肝病", "desc": "弦为肝脉，空弦并见，示肝血不足、肝气横逆。原文如“脉空弦，腹中急痛，肝病也”，以弦定位在肝，空示中虚失养，故主肝病急痛，治当兼顾肝脾。"}, {"name": "主虚损", "desc": "空主血虚、阴伤、元气不足，弦示气机不和。原文见“空为血虚”“空为元气本虚”“液脱阴枯”“虚劳已著”等，脉空弦无力，主诸虚劳损，阴血亏耗，元气大虚。"}, {"name": "主虚中夹实", "desc": "空弦并见，空为正气内虚，弦为邪气壅滞。原文如“元气本虚，诸邪又伤”“正虚邪实、痰湿壅遏”“伤血积瘀”，示虚中夹实、正虚邪恋之病机。"}, {"name": "主痰湿", "desc": "弦主气机不畅，空示正虚不运，痰湿内阻。原文“痰湿混阻”“痰湿壅遏气机”“舌苔白腻”，脉左空弦右模糊，主痰湿内蕴、气机壅滞之证。"}, {"name": "主瘀滞", "desc": "弦为气滞血瘀，空为血虚不充。原文“伤血积瘀”“气滞血凝，血结成症”，脉空弦而腹中急痛、按有头足，主瘀血内结、虚实夹杂之候。"}, {"name": "主肝脾不调", "desc": "弦为肝木偏旺，空为脾胃气弱。原文“左弦右空”“肝乘土位食减”“木旺克土”，脉空弦示肝脾不和、木土相克，治当培土御木、调和肝脾。"}], "n": {"主肝病": 2, "主虚损": 2, "主虚中夹实": 3, "主痰湿": 2, "主瘀滞": 1, "主肝脾不调": 1}, "a": {"10": "主肝病", "646": "主肝病", "1022": "主虚损", "4672": "主虚中夹实", "9097": "主虚中夹实", "9571": "主瘀滞", "12399": "主虚损", "12891": "主虚中夹实", "13710": "主痰湿", "18021": "主痰湿", "18045": "主肝脾不调"}, "t": 11, "np": 0}, "c:弦+大+浮": {"o": "浮弦大脉总起来主风、热、痰、湿等邪气壅盛，兼涉表里上下。浮主邪在表，弦主少阳、风动或气机郁滞，大主邪盛或虚阳上浮。其病机类别虽多，但可归纳为三类关系：一是外邪客表，如少阳感风、三阳合病，脉浮弦大示邪盛于表，治当和解或发汗；二是风热痰火上壅，如风热上壅清窍、湿热乘脾，脉浮弦大兼数或滑，治当清上化痰熄风；三是本虚标实，如上盛下虚，脉浮弦大而按少力，治当养阴潜阳。此外，下痢脉浮大弦示邪有外达之势，为向愈之候。诸类之间，总以邪气壅盛、气机升浮为共同特点，然有表里虚实之异，须结合兼脉与症候细辨。", "c": [{"name": "主风热上壅", "desc": "浮弦大为风热上攻之象。原文如6189段'左浮而弦大，右滑大俱数'，浮弦为风，数主热，风热上壅清窍，故耳鸣鼻塞、痰多膈热；6484段亦言'浮弦大主风热上壅'，胃中痰火生风，上扰九窍。"}, {"name": "主少阳感风", "desc": "浮为邪在表，弦主少阳，大为邪盛，浮弦大并见是风邪客于少阳经之象。7102段'脉浮弦大，当属少阳经感风'，症见背冷气急、腰痛舌黄、口燥有汗，皆少阳经气不利所致。"}, {"name": "主上盛下虚", "desc": "浮弦大而按少力，为肝肾阴亏于下，风阳上升，兼挟痰浊。14704段'脉浮弦而大，按少力，是属升多降少，上盛下虚'，症见呕、头眩心嘈，久延虑其仆中，法当养阴潜阳化痰。"}, {"name": "主三阳合病", "desc": "弦主少阳、浮主表、大示邪盛，合为三阳合病。20875段'阳明中风，脉弦浮大'，症见短气腹满、胁下心痛、鼻干嗜卧、一身悉黄、潮热哕逆，为湿热郁蒸，邪欲从表出，故与小柴胡汤或麻黄汤。"}, {"name": "主邪有外达", "desc": "下痢脉大浮弦，大浮为邪在表、正气尚能抗邪外出，弦为气机调畅，知邪有外解之势。21563段'脉浮大弦，下之当已'，21573段'下痢脉大浮弦，下当已'，皆以脉辨邪从表解而下利自止。"}, {"name": "主湿热乘脾", "desc": "脾胃脉中见浮大而弦，为心与小肠火热来乘土位，湿热相合。25158段'脾胃脉中见浮大而弦'，症见烦躁闷乱、四肢发热、口干舌干咽干，非脾胃本脉，乃心火乘脾、湿热内郁之象。"}], "n": {"主风热上壅": 2, "主少阳感风": 1, "主上盛下虚": 1, "主三阳合病": 2, "主邪有外达": 3, "主湿热乘脾": 2}, "a": {"6189": "主风热上壅", "6484": "主风热上壅", "7102": "主少阳感风", "14704": "主上盛下虚", "20875": "主三阳合病", "21563": "主邪有外达", "21573": "主邪有外达", "22672": "主湿热乘脾", "22948": "主邪有外达", "25158": "主湿热乘脾", "25820": "主三阳合病"}, "t": 11, "np": 0}, "c:滑+大": {"o": "滑大脉总以痰湿壅盛、邪气盛实为基本病机。滑主痰湿食积，大主邪盛热实，二者相合，多主实证、热证、痰证。具体而言，或痰湿内阻，或痰热壅盛，或食积停滞，或实热内炽，或风痰上扰；若兼尺脉沉弱，则为上实下虚；若滑大无力，则属正虚邪盛。各类之间常相互兼夹，如痰湿可化热成痰热，食积可生痰化火，风痰多兼热象。总以痰、热、实为核心，病位多在肺、胃、肝、脾，亦可涉及上中二焦。脉象有力者，邪实而正未衰，治当清化痰热、消积导滞；无力者，正虚邪恋，治宜扶正祛邪兼顾。", "c": [{"name": "主痰湿", "desc": "滑脉为痰湿内蕴之象，大脉示邪气壅盛。原文多称“滑主痰”“滑为湿”，如胸膈饱闷、舌苔垢腻、呕吐眩晕、痰多喘嗽等，皆痰湿阻滞气机所致。滑大有力者，为痰实壅盛；滑大无力者，为湿浊内阻而气虚。"}, {"name": "主痰热", "desc": "滑主痰，大主热，数则热甚。原文常见“滑大为痰，数为热”“痰火”“痰热壅盛”等语，症见发热、口渴、咳痰黄稠、舌绛苔糜、便秘、眩晕、头痛如破，甚则痰热生风、蒙蔽清窍。滑大数脉尤为此类典型。"}, {"name": "主食积", "desc": "滑主食积，大主积盛。原文如“食滞痰浊壅阻中焦”“滑大实积”“右关滑大主食积腹痛”，症见胸膈饱闷、嗳腐吞酸、腹痛拒按、大便不通。食积内停，胃气不得下行，脉多滑大有力，右关尤显。"}, {"name": "主实热", "desc": "大脉主邪气盛实，滑脉主痰，合而主实热壅盛。原文有“大主热”“大主火”“滑大有力主实痰实火”，症见壮热、烦渴、面红、目赤、便结、脉来有力。实热内炽，正气未衰，故脉象滑大搏指。"}, {"name": "主上实下虚", "desc": "滑大见于寸关，而尺脉沉弱或沉微，示上焦痰实壅盛，下元亏虚。原文如“两寸关脉滑大，两尺沉弱”“右脉滑大，左细弱”“上实下虚”，症见眩晕、呕吐、胃脘痛、喘嗽等，痰壅于上而肾元不足于下。"}, {"name": "主正虚邪盛", "desc": "滑大而无力，或余部无神，示正气已虚而痰浊积滞未去。原文如“六脉滑大无力”“脉大而滑，病久身凉”“右关滑大，余部无神气”，症见久病、汗多、下痢、虚损，脉象虽大而按之无力，为正虚邪实之候。"}, {"name": "主风痰", "desc": "滑主痰，大主邪盛，兼浮为风。原文如“滑大为痰，数为热，浮为风”“风痰热”“痰厥头痛”，症见眩晕、掉眩、口角牵引、头痛、呕吐痰涎。风痰上扰，壅塞清窍，脉多滑大而浮，或兼弦数。"}], "n": {"主痰湿": 29, "主痰热": 26, "主食积": 11, "主实热": 11, "主上实下虚": 4, "主正虚邪盛": 23, "主风痰": 14}, "a": {"729": "主食积", "2046": "主正虚邪盛", "2208": "主风痰", "2216": "主风痰", "2415": "主痰热", "2416": "主痰热", "2740": "主痰热", "2741": "主痰热", "3286": "主风痰", "3288": "主痰湿", "3501": "主食积", "3508": "主正虚邪盛", "3560": "主实热", "3780": "主痰湿", "3817": "主痰热", "3899": "主痰热", "4143": "主风痰", "4209": "主实热", "4266": "主痰热", "4282": "主痰热", "4302": "主上实下虚", "4741": "主风痰", "5222": "主正虚邪盛", "6002": "主痰湿", "6016": "主痰热", "6028": "主正虚邪盛", "6057": "主正虚邪盛", "6138": "主上实下虚", "6143": "主正虚邪盛", "6170": "主上实下虚", "6186": "主食积", "6196": "主正虚邪盛", "6197": "主正虚邪盛", "6203": "主风痰", "6214": "主痰热", "6218": "主上实下虚", "6296": "主食积", "6310": "主痰热", "6322": "主正虚邪盛", "6351": "主正虚邪盛", "6433": "主痰湿", "6438": "主正虚邪盛", "6465": "主痰湿", "6481": "主痰湿", "6491": "主正虚邪盛", "6492": "主正虚邪盛", "6498": "主风痰", "6509": "主痰热", "6513": "主痰湿", "6578": "主风痰", "6644": "主正虚邪盛", "6764": "主痰湿", "7482": "主正虚邪盛", "7505": "主痰热", "7822": "主痰湿", "7839": "主痰湿", "7944": "主痰湿", "8030": "主实热", "8084": "主痰湿", "8145": "主痰热", "8932": "主痰湿", "11279": "主痰湿", "11359": "主痰热", "11415": "主实热", "11422": "主痰湿", "11433": "主痰热", "11458": "主痰热", "11459": "主痰热", "11468": "主痰湿", "11476": "主痰湿", "11516": "主痰热", "13019": "主风痰", "13457": "主痰热", "13685": "主痰热", "14122": "主痰热", "14264": "主实热", "14416": "主痰热", "14562": "主风痰", "14810": "主痰热", "15218": "主正虚邪盛", "17346": "主痰湿", "17353": "主痰湿", "17365": "主痰湿", "17506": "主痰湿", "17561": "主实热", "17585": "主痰湿", "17607": "主正虚邪盛", "17783": "主实热", "18328": "主痰湿", "18330": "主实热", "18601": "主食积", "18613": "主风痰", "18643": "主正虚邪盛", "19131": "主实热", "19201": "主痰湿", "20083": "主正虚邪盛", "21824": "主正虚邪盛", "22103": "主正虚邪盛", "22217": "主正虚邪盛", "23629": "主痰湿", "23733": "主正虚邪盛", "23816": "主实热", "24633": "主痰湿", "24670": "主痰湿", "24783": "主食积", "24795": "主风痰", "24796": "主风痰", "24816": "主食积", "24832": "主痰热", "24835": "主痰热", "24886": "主实热", "24929": "主食积", "25011": "主食积", "25043": "主痰湿", "25044": "主食积", "25070": "主食积", "25071": "主痰湿", "25992": "主风痰"}, "t": 118, "np": 0}, "c:沉+小": {"o": "沉小脉总属里虚之象，沉主病在里，小主正气不足。其所主病机以阳虚、气虚、血虚为本，以水饮、寒湿、痰浊、气郁为标。具体而言，阳气衰微则水饮内停，见水肿、喘咳、癃闭；虚寒内盛则脉沉小，见畏寒、厥冷、下利；正虚邪陷则脉沉小，见于温病、伤寒后期；气血虚损则脉道不充，见经行愆期、吐血、崩漏；痰湿气郁则脉沉小兼滑弦，见痞满、呕恶、痹痛；脾肾虚损则运化失职，见泄泻、肿胀、虚秘。此外，沉小脉在伤寒汗后、肠澼下血、消渴等病中，又为邪去正安、脉证相应之吉兆。诸类之间，以正虚为本，以邪实为标，标本相兼，虚实互见，故临证当结合兼脉及症候，辨其虚损之脏腑与邪气之性质。", "c": [{"name": "主阳虚水饮", "desc": "沉小脉沉主里、小主虚，阳气衰微则水饮不化。原文如“久嗽足浮腹膨，少阴之阳已伤，故水饮欲泛”，“沉小正水饮之脉”，“水之为病，其脉沉小，属少阴”，皆示肾阳不足、水气内停。"}, {"name": "主虚寒内盛", "desc": "沉小为阳气虚衰、阴寒内盛之象。如“外阳内收，脉反沉小，始见阴候”，“脉更沉小，示寒饮内结、阳气衰微”，“寒湿身肿脉多沉小”，皆因寒邪伤阳、阳气不伸而脉沉小。"}, {"name": "主正虚邪陷", "desc": "沉小示正气不足，邪气内陷。如“屡经汗下，津枯气弱”，“邪伏于冬，而发于春，脉沉小正示邪不在表而渐入里”，“右脉稍沉而小……邪陷心包、内闭欲厥”，皆正虚不能抗邪，邪陷于里。"}, {"name": "主气血虚损", "desc": "沉小为脉道不充、气血两虚之候。如“左关尺虚濡，右寸虚软，关脉沉小。自是气血两虚”，“脉来沉小，心肝肾三阴不足”，“六脉沉小……沉小为气郁于内”，皆因气血亏虚或郁滞，脉道不充。"}, {"name": "主痰湿气郁", "desc": "沉小兼滑、弦、涩等，主痰湿内阻、气机郁滞。如“脉息小滑，小为阳虚，滑为痰饮”，“脉形沉小……痰食湿交结不解”，“六脉沉小，气郁食阻”，皆痰湿食积阻滞气机，脉沉小。"}, {"name": "主脾肾虚损", "desc": "沉小脉主脾肾阳气不足。如“肾脉沉小而无神……肾阳肾精俱亏”，“脉息沉小……脾不运化，湿气聚而为肿”，“脉右沉小……脾阳不振、气机郁滞”，皆脾肾虚衰、运化失职。"}, {"name": "主预后吉兆", "desc": "沉小脉在特定病证中主邪去正安、脉证相应之吉兆。如“伤寒已得汗，脉沉小者，生”，“肠澼下脓血，脉沉小留连者，生”，“消渴，脉沉小者，生”，皆因病邪虽盛而正气未大伤，脉证相合。"}], "n": {"主阳虚水饮": 11, "主虚寒内盛": 3, "主正虚邪陷": 5, "主气血虚损": 7, "主痰湿气郁": 14, "主脾肾虚损": 7, "主预后吉兆": 7}, "a": {"692": "主阳虚水饮", "714": "主气血虚损", "1537": "主脾肾虚损", "2870": "主气血虚损", "3363": "主虚寒内盛", "3808": "主脾肾虚损", "4280": "主脾肾虚损", "5036": "主脾肾虚损", "5165": "主正虚邪陷", "5949": "主痰湿气郁", "8606": "主气血虚损", "8709": "主气血虚损", "8976": "主痰湿气郁", "9038": "主痰湿气郁", "10227": "主阳虚水饮", "10765": "主痰湿气郁", "11462": "主脾肾虚损", "12456": "主气血虚损", "12521": "主气血虚损", "12534": "主痰湿气郁", "12696": "主痰湿气郁", "13515": "主阳虚水饮", "13568": "主正虚邪陷", "14570": "主阳虚水饮", "14658": "主正虚邪陷", "15552": "主正虚邪陷", "15641": "主虚寒内盛", "15876": "主气血虚损", "15901": "主痰湿气郁", "15907": "主痰湿气郁", "15918": "主痰湿气郁", "15925": "主痰湿气郁", "15947": "主痰湿气郁", "15959": "主脾肾虚损", "15976": "主脾肾虚损", "16237": "主阳虚水饮", "18246": "主阳虚水饮", "18253": "主阳虚水饮", "18388": "主预后吉兆", "18399": "主痰湿气郁", "18401": "主痰湿气郁", "18406": "主痰湿气郁", "18643": "主预后吉兆", "19188": "主预后吉兆", "19206": "主预后吉兆", "19226": "主预后吉兆", "19234": "主预后吉兆", "20242": "主阳虚水饮", "21824": "主预后吉兆", "23368": "主正虚邪陷", "24603": "主虚寒内盛", "24858": "主阳虚水饮", "25377": "主阳虚水饮", "25378": "主阳虚水饮"}, "t": 54, "np": 0}, "pc:右+弱+软": {"o": "右·弱软脉总属虚象，以气虚、脾虚为核心，常兼他部脉象而呈复合病机。右寸软弱主肺气虚，右关软弱主脾虚湿盛，右尺弱主肾阳不足；若兼左脉弦长、弦细，则为肺虚肝旺、木行乘金；兼左脉细数，则为气阴两伤之上损；兼左脉数而有力或弦滑，则为正虚邪恋、虚实夹杂；兼左脉散乱，则为气阴外脱之危候。要之，软弱脉以正气不足为根本，或见于纯虚，或见于虚中夹实，总以右部候气、候脾肺为定位依据，他部脉象则示兼夹之邪与虚损之所在。", "c": [{"name": "主脾虚湿盛", "desc": "右脉软弱多主脾土虚弱，运化失职，湿气内停。8958段明言右脉软弱、左关带弦，为脾经不足、湿气有余，因于气为肿；15802段右软尺弱，为脾肾火土并衰，不饥纳少。脾虚不能运湿，故脉见软弱。"}, {"name": "主气血两虚", "desc": "右脉软弱兼左脉细弦或散乱，示气血两亏。13564段左脉细弦、右脉软弱，三疟后气血两亏，肝肾脾胃俱虚；6054段右手软弱、左手散乱，为汗多脉不敛、气阴外脱之危候。软弱主气衰，兼他脉虚象则气血俱损。"}, {"name": "主正虚邪恋", "desc": "右脉软弱而左脉数而有力或弦滑，为正虚邪实之候。6248段左脉数有力、右脉软弱，为阳明少阳并病，热盛而正气已伤；14276段左弦滑、右弱不应指，为痰热内结而阳气不布。软弱示正虚，他脉示邪实。"}, {"name": "主肺虚肝旺", "desc": "右寸软弱兼左脉弦长或弦细，为肺金气虚、肝木亢逆。6043段右寸软弱、关滑，左脉弦长上鱼际，为木行乘金、亢而不下；16055段右软弱、左弦细，为肺金虚而肝火冲肺。右寸候肺，软弱即肺气不足。"}, {"name": "主虚损上损", "desc": "右脉软弱兼左脉细数，为气阴两伤、病属上损。13625段久咳痰稠、上午发热，左脉细数、右脉软弱，断为上损，细数为阴亏火动，软弱为脾肺气馁。软弱示气分不足，合细数则虚损之象已成。"}], "n": {"主脾虚湿盛": 2, "主气血两虚": 4, "主正虚邪恋": 5, "主肺虚肝旺": 3, "主虚损上损": 4}, "a": {"6043": "主肺虚肝旺", "6047": "主气血两虚", "6054": "主虚损上损", "6248": "主正虚邪恋", "6337": "主肺虚肝旺", "6341": "主气血两虚", "6348": "主虚损上损", "6541": "主正虚邪恋", "8958": "主脾虚湿盛", "13564": "主气血两虚", "13625": "主虚损上损", "13753": "主正虚邪恋", "14276": "主正虚邪恋", "14652": "主气血两虚", "14733": "主虚损上损", "14899": "主正虚邪恋", "15802": "主脾虚湿盛", "16055": "主肺虚肝旺"}, "t": 18, "np": 0}, "pc:左+弦+紧": {"o": "左弦紧脉总以弦为肝郁气结、紧为邪实拘急为纲，所主病机可归为肝郁火盛、寒凝痛实、饮邪未净、疟湿余邪、温疫火郁、风中经络、瘀血内蓄七类。其核心在于邪壅气滞、肝胆经气不利：弦紧并见，或化火刑金、或寒凝作痛、或饮停湿阻、或疫火鸱张、或风客经络、或瘀血内停，皆因实邪阻滞、气机拘急所致。各证虽异，然总不离“邪实气壅”四字，故脉象多兼数、滑、沉、浮等，以辨寒热表里与在气在血。", "c": [{"name": "主肝郁火盛", "desc": "弦为肝脉，紧主邪实拘急。左脉弦紧见咽痛失音、咳痰不爽，为木火刑金、肝火循经上灼；或邪热化火熏灼肺胃，咽赤碎痛、环口热泡、烦渴，弦紧示火郁不散，恐热入血室。"}, {"name": "主寒凝痛实", "desc": "紧主寒主痛，弦主气机拘急。左脉弦紧见于少腹剧痛、睾丸胀大、面青畏寒，为寒凉攻伐后寒遏中下二焦、气机壅塞；或湿热内犯肝经，少腹作痛呕吐，弦紧兼数示邪壅气滞、湿热化火。"}, {"name": "主饮邪未净", "desc": "弦紧主饮邪内结、气机不利。咳减而左脉沉细、右脉弦紧，说明饮邪未尽除；遍身骨痛为久病劳损，脉仍弦紧示饮邪未化，故以甘温调营卫、复胃气，气旺则饮化。"}, {"name": "主疟湿余邪", "desc": "弦主少阳疟邪，紧主寒湿内结。疟虽止而左脉弦紧，右大而缓，舌白未化，说明寒湿余邪仍阻三焦，余湿未清；脉象弦紧与大缓并见，故方仍照服，去其不宜之品。"}, {"name": "主温疫火郁", "desc": "弦紧主邪势鸱张、郁于少阳，兼滑数则温疫化火。春温疫疠发热咽痛、遍身丹赤、痧点连片，右脉滑数左脉弦紧，示火邪充斥内外、蔓延三焦，恐火从内窜而致神昏发痉。"}, {"name": "主风中经络", "desc": "弦为肝脉，紧主风主寒。左关弦紧为风中肝胆，见口眼㖞斜；左脉弦紧为少阳寒邪，见风寒眩晕；寒湿痢少阳受邪亦见弦紧。总属风邪或寒湿外客少阳、肝胆经络，气机拘急。"}, {"name": "主瘀血内蓄", "desc": "产后恶露甚少即停，过食厚味致瘀血内蓄，胸腹胀闷、错语、牙关紧闭、小腹膨胀。脉虚而滞、左脉弦紧，虚为体虚，滞为瘀阻，弦紧主痛主瘀，示瘀血停滞、气机壅塞，非纯虚可补。"}], "n": {"主肝郁火盛": 3, "主寒凝痛实": 3, "主饮邪未净": 1, "主疟湿余邪": 1, "主温疫火郁": 2, "主风中经络": 2, "主瘀血内蓄": 1}, "a": {"4842": "主肝郁火盛", "5506": "主饮邪未净", "5581": "主疟湿余邪", "7031": "主肝郁火盛", "7396": "主温疫火郁", "7428": "主温疫火郁", "10732": "主肝郁火盛", "15646": "主寒凝痛实", "16033": "主瘀血内蓄", "24623": "主风中经络", "24795": "主寒凝痛实", "24796": "主风中经络", "25001": "主寒凝痛实"}, "t": 13, "np": 0}, "pc:左+大+浮": {"o": "左·大浮脉总以浮大为主象，浮主表、大主热盛，故所主病机以表邪与热盛为核心。表邪包括外感风、寒、湿、暑等邪在表，如太阳风湿、阳明寒湿、表邪未散之嗽血、遗尿表邪等；热盛则见暑热充斥、风热内传、痰热生风。浮大又主风动，因热盛化风或虚风内动，如偏头风、痰热生风。此外，浮大亦主暑热、风湿、寒湿等特定邪气。诸类之间，表邪与热盛常相兼，风动多由热盛或虚风所致，风湿、寒湿、暑热则各具邪气特性。总归左脉浮大提示邪在表或热盛动风，须结合兼脉及症候辨其具体病机。", "c": [{"name": "主表邪", "desc": "左脉浮大，浮为邪在表，大示邪盛。原文如遗尿之脉“若见浮大，外有表邪”，外感嗽血“左脉浮大，表邪未散”，风湿酸软“左脉浮大…太阳风湿”，寒湿痢“右脉浮大，阳明寒湿”，均以浮大主表邪未散或风湿、寒湿在表。"}, {"name": "主热盛", "desc": "大为热盛之象，浮大常主表热或里热鸱张。如暑症“左脉浮大、六部俱数”为暑热充斥表里；风热内传“左脉大而见浮”主阳明少阳里热；痰热生风“左脉浮大，热生风也”，皆因大主热盛，热盛则脉体宽大。"}, {"name": "主风动", "desc": "左脉浮大，浮为风，大主热，热盛则生风。如虚风内动“脉左浮大…虚风内动之象”，风居空窍致偏头风；痰热生风“左脉浮大，热生风也”，湿痰瘀血凝结筋络，热盛化风，故浮大主风热内动。"}, {"name": "主虚风", "desc": "左脉浮大亦可见于虚风内动，因气血不足，虚风上扰。如偏头风案“脉左浮大，左属肝，浮大为虚风内动之象”，症见自汗、鼻出冷涕、火升便艰，非外风实邪，乃虚风挟火，故浮大主虚风。"}, {"name": "主暑热", "desc": "左脉浮大兼六部俱数，主三阳合病暑症。原文“左脉浮大、六部俱数”伴额痛遍身痛、口干苔黄、小水赤痛、烦躁不睡，为暑热鸱张、邪在三阳，浮大数脉正合暑热充斥表里之机。"}, {"name": "主风湿", "desc": "左脉浮大或反沉伏，主太阳风湿；右脉浮大或反沉伏，主阳明风湿；六脉弦大主少阳风湿。浮大为风湿在表，沉伏为邪郁不达，弦大主风湿拘急，故浮大主风湿酸软之病机。"}, {"name": "主寒湿", "desc": "右脉浮大主阳明寒湿，左脉浮紧主太阳寒湿。寒湿在表则脉浮大，寒湿内伏则脉沉紧，少阳受邪则脉弦紧。浮大示寒湿客于阳明之表，故寒湿痢见右脉浮大。"}], "n": {"主表邪": 3, "主热盛": 3, "主风动": 1, "主虚风": 2, "主暑热": 2, "主风湿": 1, "主寒湿": 1}, "a": {"6169": "主暑热", "6464": "主暑热", "7044": "主热盛", "8326": "主虚风", "10964": "主风动", "15277": "主虚风", "18419": "主热盛", "19361": "主热盛", "24619": "主表邪", "24639": "主表邪", "24729": "主表邪", "24975": "主风湿", "25001": "主寒湿"}, "t": 13, "np": 0}, "pc:左+弦+软": {"o": "左弦软脉总以弦为肝木偏旺、气机郁逆，软为正气不足或湿邪内滞为纲。其主病机可归纳为肝郁气逆、阴血亏虚、脾虚湿困、痰热内蕴、湿热下注及少阳阳明合病数类。弦与软并见，反映虚实夹杂之象：弦主肝旺、气郁、木火，软主正虚、湿滞、阴伤。各类之间常相互兼夹，如肝郁侮土则脾虚湿困，阴血亏虚则肝失柔养而阳亢，正虚痰盛则痰热内闭，气虚阴亏则湿热下注。总以肝木失调为中心，涉及脾、胃、肾及气血津液，病性多虚实并见、寒热错杂，治当标本兼顾。", "c": [{"name": "主肝郁气逆", "desc": "左弦为肝气升逆或郁怒所伤，气失调达。原文见肝气升逆作痛、呕吐、齿痛，或郁怒伤肝、木火尚炽。弦主肝旺，软示肝经本部正气偏弱，故脉弦软并见，主肝郁气逆兼风火上扰之病机。"}, {"name": "主阴血亏虚", "desc": "左软为阴血亏虚、肝失柔养，弦为木旺失柔。原文见失血后脉左软弦、白浊年余阴血亏虚，或温病后肝阴不足、虚风内动。软弦不任重按，示阴血不足而肝阳偏亢，故主阴血亏虚、肝失所养之病机。"}, {"name": "主脾虚湿困", "desc": "右软主胃津日损或湿邪留滞，左弦为木郁侮土。原文见右弦左软而腹胀、下焦无火津不上供，或左软右弦而湿邪留滞、中气失畅。软脉主湿、主虚，弦主木郁，故主脾虚湿困、木不疏土之病机。"}, {"name": "主痰热内蕴", "desc": "左弦软兼右滑实或虚大而滑，滑主伏痰内盛。原文见重听案右软滑实为痰气内结，温病案右虚大而滑为伏痰内盛。弦软示正虚木旺，滑实示痰热壅盛，故主正虚邪陷、痰热内闭之病机。"}, {"name": "主湿热下注", "desc": "左弦为肝阳偏强、郁怒所伤，右软为气虚阴亏，湿热下注。原文见疼痛淋浊、火掩精关，乃湿伤气、热伤阴。脉象示气虚阴亏、肝阳偏亢而湿热下注，故主湿热下注、正虚邪恋之病机。"}, {"name": "主少阳阳明合病", "desc": "右软主阳明湿滞，左弦主少阳郁热。原文见身热不扬、汗出、目赤面垢、呕恶吞酸、胸满引背、发疹，脉右软左弦。软为湿困，弦为热郁，故主少阳阳明合病、湿滞热郁之病机。"}], "n": {"主肝郁气逆": 1, "主阴血亏虚": 3, "主脾虚湿困": 2, "主痰热内蕴": 2, "主湿热下注": 1, "主少阳阳明合病": 1}, "a": {"2258": "主脾虚湿困", "4616": "主阴血亏虚", "9592": "主阴血亏虚", "9758": "主肝郁气逆", "10009": "主阴血亏虚", "10520": "主脾虚湿困", "12588": "主湿热下注", "13257": "主痰热内蕴", "13893": "主痰热内蕴", "18079": "主少阳阳明合病"}, "t": 10, "np": 0}, "pe:左+动": {"o": "左动脉所主病机，总以“动”为象，然有虚实之别。实者多因阳升火动、郁结气滞、中焦壅滞、燥屎内结，脉动而有力，兼数、大、弦、涩、滑等，如六部动大而数、沉弦、沉涩应指。虚者多因冲脉气逆、虚损不固，脉动而无力，兼涩弱、虚数等，如左脉涩弱、左弦细右虚数。冲脉气逆为动脉核心病机，因冲脉隶于肝肾，下元虚则冲气上逆，或阳升火动引冲脉升动，故冲脉动与阳升火动常相兼为患。郁结、壅滞、燥屎等实邪阻滞气机，亦可致动脉，然其动多兼实象。邪恋正复之动脉轻微，为病后余波。诸类之间，虚实可转化，如虚损不固可致冲气上逆，阳升火动可灼津成燥屎，临证当脉症合参，分其主次。", "c": [{"name": "主冲脉气逆", "desc": "动脉见于尺中或脐旁，为冲脉失摄、气逆上冲之象。原文如“冲脉震动则诸脉俱逆”、“冲脉升动，络血不宁”、“肝肾衰则冲脉动”，皆因下焦肝肾虚损，冲脉不能安守，动气上逆，致眩晕、咳呛、涎沫上溢等症。"}, {"name": "主阳升火动", "desc": "动脉兼数、大，为阳气不潜、气火升腾之征。如“阳不潜伏，冲脉升动”、“六部动且大而数，示阳气亢奋、热扰气血”、“跳动为火气冲动”，皆因五志过极或水亏木旺，阳升化火，鼓动气血而脉动。"}, {"name": "主虚损不固", "desc": "动脉见涩弱或与虚脉并见，主肝肾精血亏虚、根蒂不固。如“左脉涩弱……肾气少纳”、“左弦细右虚数，肝肾根蒂不固”、“无常则宗气大虚”，皆因下元亏虚，不能摄纳，冲气浮越而脉动。"}, {"name": "主郁结气滞", "desc": "动脉兼沉弦或涩，主气机郁滞、升降失常。如“沉中带弦，沉主里，弦主郁”，因怒气郁结，肝失疏泄，水湿停聚；“按之有力，举之似涩”，为实中夹瘀、痰瘀互结，气机壅塞而脉动。"}, {"name": "主中焦壅滞", "desc": "动脉见于关部，兼滑涩，主谷食碍胃、痰食内滞。如“左似滑，右似涩……动气上乎左，谷食碍乎胃”、“动气在中脘建里，谷气壅于中焦”，皆因中焦运化失职，气机壅滞，脉动不安。"}, {"name": "主燥屎内结", "desc": "动脉见于寸部，兼沉涩应指，主燥屎内结、腑气不通。如“左寸发动，关尺沉，右寸关沉涩如有物应指……断为燥屎”，因金燥火郁日久，燥屎内结，气机被阻而躁动，脉见动而沉涩。"}, {"name": "主邪恋正复", "desc": "动脉轻微或与平静脉并见，主余邪未清、正气渐复。如“六部平静而流利，肾间动脉亦静……更有邪之余动”、“脉宁静五动少躁……动气依前未全收”，示病后气机偶有扰动，但整体向愈。"}, {"name": "脉候待参", "desc": "仅录动脉至数或形态，未附症候论断，病机无从推求，存脉待参。"}, {"name": "宗气外泄", "desc": "虚里动脉应手无常，为宗气大虚、上焦气弱、胃之大络失守之象。"}], "n": {"主冲脉气逆": 2, "主阳升火动": 5, "主虚损不固": 5, "主郁结气滞": 1, "主中焦壅滞": 3, "主燥屎内结": 1, "主邪恋正复": 3, "脉候待参": 1, "宗气外泄": 1}, "a": {"319": "主冲脉气逆", "1007": "主阳升火动", "2113": "主虚损不固", "2903": "主郁结气滞", "2923": "主邪恋正复", "2925": "主邪恋正复", "2937": "主中焦壅滞", "2946": "主中焦壅滞", "2948": "脉候待参", "2949": "主中焦壅滞", "2956": "主邪恋正复", "2961": "主虚损不固", "3061": "主燥屎内结", "3092": "主阳升火动", "4451": "主阳升火动", "5006": "主虚损不固", "8553": "主虚损不固", "10425": "主阳升火动", "11484": "主阳升火动", "15724": "宗气外泄", "18621": "主虚损不固", "23671": "主冲脉气逆"}, "t": 22, "np": 0}, "pe:寸+微": {"o": "寸·微脉总起来主上焦阳气虚衰与气机失守，兼及寒痰实邪壅遏胸中。其核心病机为“微”象所反映的正气不足——或肺气亏虚、或神气浮散、或下焦阳衰饮逆、或荣卫两虚；然寸部独微又常与实邪阻遏相关，如寒痰壅胸之寸微浮、热结深伏之寸更微，皆因邪阻而脉道不利，非纯虚可比。各类之间以“虚”为共同底色：虚损、气脱、阳衰、荣卫两虚属正虚一端；寒痰壅胸、热结似阴属邪实致微一端，虚实之间又可转化，如阳虚饮逆即虚中夹实。临证须结合尺脉、兼脉及症候，辨其微为虚、为脱、为邪遏，不可一概而论。", "c": [{"name": "主虚损", "desc": "寸脉微主上焦阳气不足、肺气亏虚。原文如“寸脉微，名曰阳不足”，右寸微主肺气有损，寸口脉微或见濡软、沉细，皆肺虚之征。微为气血衰微之象，寸部应上焦，故见气怯神弱、咳嗽有汗、纳少便溏等虚劳之候。"}, {"name": "主气脱", "desc": "寸脉微而按之忽无举之忽有，或如水上浮麻不分至数，为神气浮散、大气下陷之候。原文见谵妄颠仆、精气下脱，或骤得下血、气息奄奄，左部脉皆不见。微而无力，根本动摇，故主气脱危候。"}, {"name": "主阳衰饮逆", "desc": "寸脉沉而尺脉微，或寸微尺微并见，主下焦阳虚、饮停上焦、冲气上逆。原文见手足厥逆、气从少腹上冲胸咽、面翕热如醉、小便难，皆阳虚不能制水、饮邪随冲气上下之象。微为阳衰，沉为饮停。"}, {"name": "主寒痰壅胸", "desc": "寸脉微浮，主寒痰实邪壅塞胸中、阳气被遏。原文见胸中痞硬、气上冲咽喉、不得息，断为“胸中有寒”，当吐之。微浮示邪在上焦，寸主胸膈，故寒痰阻滞、气逆不降而脉见微浮。"}, {"name": "主热结似阴", "desc": "寸脉更微而脉微如丝，反见腹满苔焦、谵语狂乱、通身冰凉，为热结深伏、营气不达四肢之阳极似阴证。微非虚寒，乃热结阻遏脉道，故脉微而声音烈烈、扬手掷足、渴欲饮冷，当细辨。"}, {"name": "主荣卫两虚", "desc": "寸口脉微而涩，微者卫气不行，涩者荣气不足。原文见面色黄青、寒栗、咳逆、唾腥吐涎沫，荣卫俱微则根叶枯槁。寸微主阳不足，卫外不固；涩主血少，荣养失充，故主荣卫两虚之候。"}], "n": {"主虚损": 5, "主气脱": 2, "主阳衰饮逆": 5, "主寒痰壅胸": 1, "主热结似阴": 1, "主荣卫两虚": 1}, "a": {"3775": "主气脱", "15919": "主虚损", "18293": "主热结似阴", "19812": "主气脱", "21654": "主阳衰饮逆", "21803": "主虚损", "21807": "主虚损", "22033": "主阳衰饮逆", "22891": "主荣卫两虚", "24710": "主虚损", "24881": "主虚损", "25347": "主阳衰饮逆", "25348": "主阳衰饮逆", "25777": "主阳衰饮逆", "27847": "主寒痰壅胸"}, "t": 15, "np": 0}, "pe:两+虚": {"o": "虚脉总主正气亏虚，包括气血不足、阳气衰微及脏腑功能减退。其基本特征为脉来虚耎无力，按之空豁。从所主病机看，虚脉可单独出现，主气血大虚、气虚阳衰，如高年发背脓血多、脾肾阳虚下痢、气虚眩晕诸部皆虚；亦可专见于尺部，主肾虚不摄，见内中风、喘逆等气逆上脱之证；又常见于邪退正伤或正虚邪恋之时，如风温后、少阳症后、痈脓已成，示气阴耗伤或正不胜邪；若虚脉与弦、洪、滑、数等实脉并见，则提示虚中夹实，如暑热伤气兼痰火、阴火太旺水亏火炎。各类之间以正虚为共同基础，或纯虚，或虚中夹实，或虚而气逆，总不离气血阴阳之亏。", "c": [{"name": "主气血大虚", "desc": "虚脉主气血亏耗，脉道不充。如两脉虚耎无力，因高年气血已亏、脓血出多、饮食不进，致气血大虚；两关虚耎，为脾胃气虚、统摄无权而远血；关脉虚耎，因劳心伤脾、气血不足。皆以虚耎无力为据。"}, {"name": "主气虚阳衰", "desc": "虚脉亦主气虚阳衰，脏腑功能减退。两尺细弱无力、脾脉更虚，为脾肾阳虚、寒邪内生之下痢白脓；右寸虚肺气不足、右关虚中气不足、左寸虚心气不足、左关虚肝胆气弱、两尺虚肾气不足，总属气虚眩晕。"}, {"name": "主肾虚不摄", "desc": "两尺脉虚专主肾气不固、下焦亏虚。两尺脉虚，肾气不摄，冲胃之气上逆，肝风内动，血随气逆充塞脑络；两尺脉虚，肾不纳气，喘逆气欲上脱，需人参、赭石导气归肾。皆以尺虚为根本亏虚之征。"}, {"name": "主正虚邪恋", "desc": "虚脉见于邪退正伤或正虚邪留之际。风温后邪净胃不开，两脉甚虚，为气阴耗伤、正虚未复；少阳症脉转两寸虚、脉散，示邪减而气阴已伤；痈脓已成色脉两虚，为正不胜邪、当补托透脓。"}, {"name": "主虚中夹实", "desc": "虚脉可与实脉并见，提示正虚而邪实壅盛。左脉弦大、右脉虚大，两关洪滑，为暑热伤气而痰火壅盛、肝火亢盛；肝脉甚虚而两尺洪大且数，为阴火太旺、水亏火炎。虚脉在此示正气已伤，实脉示邪火痰积。"}], "n": {"主气血大虚": 4, "主气虚阳衰": 1, "主肾虚不摄": 4, "主正虚邪恋": 3, "主虚中夹实": 3}, "a": {"759": "主气血大虚", "3622": "主虚中夹实", "6061": "主正虚邪恋", "6125": "主虚中夹实", "6355": "主正虚邪恋", "7132": "主正虚邪恋", "12111": "主肾虚不摄", "12112": "主肾虚不摄", "12257": "主虚中夹实", "15054": "主气血大虚", "15529": "主气血大虚", "15748": "主气血大虚", "19584": "主肾虚不摄", "20409": "主肾虚不摄", "24801": "主气虚阳衰"}, "t": 15, "np": 0}, "pe:六+涩": {"o": "涩脉总主气机不畅、血行不利，其病机涵盖气滞、血瘀、津伤血少、痰饮、肺气不利及气虚阳弱诸类。从原文看，涩脉既可因实邪阻滞（气滞、痰饮、瘀血）致脉道不利，亦可因津血亏少、气虚阳弱而脉道不充。各证之间常相互兼夹：气滞可致血瘀，痰饮可阻气机，津伤血少可加重气滞，气虚阳弱可生寒凝。故涩脉所主非单一虚候，须结合兼症辨其虚实：实者多因气、痰、瘀阻遏，虚者多因津血亏少或气阳不足。总以“脉道涩滞、气血运行不畅”为共同病机核心。", "c": [{"name": "主气滞", "desc": "涩脉往来艰涩，为气机郁滞、升降失司之象。如六脉涩滞而胁痛吐臭痰、恶心食不下，因清气不升、浊气郁于少阳之络；又如六脉俱涩而胸膈胀闷如绳束缚，乃气滞不行、痰饮内阻。气机不畅则脉道不利，故涩。"}, {"name": "主血瘀", "desc": "涩脉细迟往来难，主瘀血内停、经络闭塞。如室女月事闭塞、两腿痿废、抑搔不知疼痒，六脉皆涩，知经络为瘀血闭塞；又如温病脉六七至而涩，经水适行，为热入血室、血结不行。瘀血阻络，脉道涩滞，故主血瘀。"}, {"name": "主津伤血少", "desc": "涩脉主血少津伤、脉道不充。如汗大出不止、恶风发热、遍身疼痛，六脉皆涩，乃汗多津伤、营卫不和、气血涩滞；又如素本虚弱、误用补敛太过，月事闭塞而脉涩，亦因血少而涩。津血亏少，脉道失润，故往来艰涩。"}, {"name": "主痰饮", "desc": "涩脉主痰饮内阻、气血不畅。如头晕且痛、起则倒仆、胸膈胀闷如绳束缚、呕吐食不得入，六脉俱涩，为痰饮挟木火之势上逆作晕。痰饮阻滞气机，脉道不利，故见涩象。"}, {"name": "主肺气不利", "desc": "涩脉主肺病气滞、宣降失司。如两臂痛甚、两手灼热、溺色如泔，六脉俱涩，喉有喘呼，引《内经》肺所生病上气喘满、臂痛、掌中热、溺色变。肺气不利，气机壅滞，脉道涩滞，故主肺气不利。"}, {"name": "主气虚阳弱", "desc": "涩脉亦主气虚阳弱、寒凝气滞。如脾胃气虚、不思饮食，诸病气虚者，脉见涩而紧，或六脉沉细微弱而涩。气虚无力推动，阳弱寒凝，脉道不畅，故涩而无力。此涩非独血少，亦因气阳不足。"}], "n": {"主气滞": 2, "主血瘀": 2, "主津伤血少": 2, "主痰饮": 2, "主肺气不利": 1, "主气虚阳弱": 1}, "a": {"3663": "主气滞", "4247": "主气滞", "6050": "主津伤血少", "6063": "主痰饮", "6344": "主津伤血少", "6357": "主痰饮", "17364": "主肺气不利", "20269": "主血瘀", "21797": "__np", "27102": "主气虚阳弱", "27863": "主血瘀"}, "t": 11, "np": 1}, "pe:寸+浮": {"o": "寸·浮脉总以“阳浮气盛、病位在上”为基本象义，寸候上焦，浮主表、主阳、主上越。所主病机可归纳为表邪、上焦热实、痰湿壅上、虚阳外浮、气逆上壅、脏结寒凝六类。其间有虚实寒热之异：实者多因外邪袭表、热结胸膈、痰湿壅肺、气逆上冲，脉多浮而有力，症见寒热、胸痛、咳逆、气冲等；虚者多因阳气虚浮、阴亏不敛、脏气虚寒，脉多浮而无力或兼细紧，症见自汗、厥逆、下利、神蒙等。诸类虽异，皆不离寸部浮脉“阳气浮越于上、病位偏于上焦”之总机，临证须合兼脉、按力及分部以辨虚实寒热。", "c": [{"name": "主表邪", "desc": "寸浮主外邪袭表，卫阳浮盛。原文如“尺寸俱浮，头身俱痛，翕翕发热”，浮为表邪弥漫之象；又“寸口脉浮而盛者，病在外”，明示浮盛主表。风热、寒邪在表，寸浮皆可见。"}, {"name": "主上焦热实", "desc": "寸浮主阳热郁于上焦，或热与水饮互结。结胸证“寸脉浮，关脉沉，按之痛”，浮示阳热在上，与胸中水饮相结；又有“久痰宿于胸中，气上冲”而寸浮，皆上焦实邪壅盛之象。"}, {"name": "主痰湿壅上", "desc": "寸浮主痰湿风邪壅阻上焦。如“左寸脉息上浮，关部弦数”，为脾湿痰被肝火冲激、累及心包；浮滑并见则风痰恋肺，咳逆音嘶。浮示病位在上，痰湿内蕴故脉浮。"}, {"name": "主虚阳外浮", "desc": "寸浮主阳气虚浮不敛，根本亏虚。如“右寸浮而不敛”为阳虚阴亏、卫表不固，自汗如雨；“左寸浮散，按之无神”为心气虚浮、神不守舍。浮而无力无神，是虚阳上浮之征。"}, {"name": "主气逆上壅", "desc": "寸浮主气机逆上，中下焦虚竭。如妊妇“两寸浮，两尺如无”，呕恶不止，气逆于上而根本空虚；又有“气上冲咽喉不得息”而寸浮，皆气逆上壅、病位偏上之象。"}, {"name": "主脏结寒凝", "desc": "寸浮主阳气浮越，脏气虚寒内结。脏结证“寸口脉浮，关上小细沉紧”，浮为阳气浮越于上，关部小细沉紧示脏寒阴结、气血凝滞，故饮食如故、时时下利，属正虚寒结之候。"}], "n": {"主表邪": 2, "主上焦热实": 2, "主痰湿壅上": 3, "主虚阳外浮": 5, "主气逆上壅": 2, "主脏结寒凝": 3}, "a": {"5823": "主痰湿壅上", "8312": "主气逆上壅", "10415": "主虚阳外浮", "10671": "主痰湿壅上", "12371": "主表邪", "16658": "主气逆上壅", "18890": "主上焦热实", "18891": "主脏结寒凝", "20841": "主脏结寒凝", "21095": "主虚阳外浮", "21392": "主痰湿壅上", "21803": "主表邪", "21807": "主虚阳外浮", "21922": "主脏结寒凝", "22970": "主上焦热实", "24738": "主虚阳外浮", "24931": "主虚阳外浮"}, "t": 17, "np": 0}, "c:滑+沉+涩+迟+实+芤": {"o": "沉迟滑实涩芤脉总起来主里实夹瘀、寒湿痰积与死血为患。沉迟滑实一类，以沉主里、迟主寒、滑主湿痰、实主邪盛，合示寒湿、积痰等实邪内蕴，阻滞经络，气血不达四末而见麻木；沉涩而芤一类，以涩主血滞、芤主血虚或瘀血，合示死血内停，兼有血虚。两类均属里证，一偏寒湿痰积之实，一偏瘀血内阻之虚实夹杂。原文以脉辨麻木之因，明示沉迟滑实与沉涩而芤各主不同病机，须详辨寒湿、积痰、死血之殊。", "c": [{"name": "主寒湿", "desc": "沉迟滑实脉中，沉主里、迟主寒、滑主湿、实主邪盛，合而示寒湿内蕴。原文言麻木兼作有寒湿之殊，脉见沉迟滑实，故沉迟滑实可主寒湿积于经络，阳气不达四末。"}], "n": {"主寒湿": 2}, "a": {"3924": "主寒湿", "4308": "主寒湿"}, "t": 2, "np": 0}, "c:数+细+滑+软": {"o": "滑数细软脉总属湿热未清、正气已伤、邪有内陷之势的复合脉象。滑主湿浊内蕴，数主余热未清，细软主正气已伤，三者并见，反映湿、热、虚三者交织，而以湿热内蕴为病机核心。因正虚不能胜邪，热邪易扰心神，故见神糊谵语、舌绛，有邪陷心包之虞。三类病机相互关联：湿热内蕴为病之本，正虚邪恋为病之势，邪陷心包为病之变。脉象虽分三端，实为一体，提示病情危重，治当辛凉清热化邪，兼顾正气，防其内陷。", "c": [{"name": "主湿热内蕴", "desc": "脉滑主湿浊，数主热，滑数相合为湿热交蒸之象。原文谓‘滑主湿浊内蕴，数示余热未清’，且身热未解、胸脘略舒、舌带少绛，皆湿热郁遏气分之征，故滑数细软脉首主湿热内蕴未清。"}], "n": {"主湿热内蕴": 1}, "a": {"1921": "主湿热内蕴"}, "t": 1, "np": 0}, "c:数+弦+滑+大": {"o": "弦大数滑脉总起来主痰积、火热与暑邪内伏，三者相互交织。弦主痰饮，滑主痰积，大数主火，故脉象反映痰积内蕴、火热亢盛，又因暑邪内伏，与胃中痰积互为患。原文以‘胃中痰积未清’为核心，兼见胃火上升鼻衄，说明痰积是基础，火热是痰郁所化，暑邪是外因诱发，共同构成痰热互结、暑邪内伏之病机。治疗宜豁痰疏理清热，正针对痰、热、暑三者。", "c": [{"name": "主痰积", "desc": "脉弦滑并见，弦主痰饮，滑主痰积，原文谓‘胃中痰积未清’，且脉象弦大带滑，反映痰积内伏胃中，故主痰积为患。"}], "n": {"主痰积": 1}, "a": {"11408": "主痰积"}, "t": 1, "np": 0}, "c:数+细+小+濡": {"o": "濡细小数脉总起来主下焦湿热蕴结、阴络受损，兼见肝肾阴虚、气化不利之机。濡细主湿、主虚，小数主热，合而见于尺部，则湿、热、虚三者交织于下焦。原文以尿血涓滴、茎中鲜血频滴、小便疼刺难出、大便难解为主症，明言尺脉濡细小数主下焦湿热蕴结、阴络受损；又述肝肾阴虚、湿热下注、气化不利。三类病机相互关联：湿热蕴结下焦为标，阴虚火旺为本，气化不利为果，共同构成虚实夹杂、湿热伤络之候。", "c": [{"name": "主下焦湿热", "desc": "濡细小数脉中濡细主湿、小数主热，合而示下焦湿热蕴结。原文尺脉濡细小数，伴尿血涓滴、茎中鲜血频滴、小便疼刺难出，皆湿热下注、灼伤阴络之征，故主下焦湿热蕴结、阴络受损。"}], "n": {"主下焦湿热": 1}, "a": {"15601": "主下焦湿热"}, "t": 1, "np": 0}, "pc:左+数+弦+细+小": {"o": "左关尺数弦细小脉，总起来主肝郁化火、阴亏火旺之病机。弦主肝郁，细小数主阴亏火旺，三者相合，提示肝气郁结、郁久化火、阴液亏耗的病理格局。其病机类别包括肝郁、阴亏火旺、火郁筋脉，三者相互关联：肝郁为始动因素，郁久化火则火旺，火旺伤阴则阴亏，阴亏又加重火旺，形成恶性循环；火郁筋脉则见局部酸痛，火迫膀胱则见溺痛尿血。此脉象虽见于左关尺，但病机涉及肝、肾、膀胱及筋脉，属本虚标实、虚实夹杂之候，治疗需疏肝解郁、滋阴降火并举，不可纯用苦寒直折。", "c": [{"name": "主肝郁", "desc": "脉左关尺弦，弦为肝郁之象。原文谓‘弦主肝郁’，患者新嫁月余，情志不遂，肝气郁结，气机不畅，故脉见弦。肝郁化火，下迫膀胱，则溺痛尿血；火郁筋脉，则手腕酸痛。"}], "n": {"主肝郁": 1}, "a": {"15849": "主肝郁"}, "t": 1, "np": 0}, "c:数+沉+浮+小": {"o": "浮小沉数脉在此案中并非沉数，而是浮小而不沉数，按之少有力。总起来主邪已外达、正气渐复、胃气渐旺之病机。浮主邪在表，小主正气未充，按之少有力主胃气渐振。三者相互关联：邪从表解则脉浮，正气未充则脉小，胃气渐复则按之有力。此脉象示疾病向愈之机，故治疗以健脾益气、清热和胃为主，先以四君子汤加味，继以香砂六君子汤调理而安。", "c": [{"name": "主邪在表", "desc": "脉浮为邪气在表之征。原文'脉浮小而不沉数'，浮脉主表，示邪气外达，未入于里，故当从表解，如案中以四君子汤加黄芩等健脾清热而愈。"}], "n": {"主邪在表": 1}, "a": {"15888": "主邪在表"}, "t": 1, "np": 0}, "c:数+滑+大+浮": {"o": "浮大滑数脉总属阳脉，其核心病机为阳热亢盛、气血鼓动。原文张景岳以「浮大滑数之类皆阳也」与「沉微细涩之类皆阴也」对举，将脉之阴阳统摄病机，为医道纲领。拆分而言，浮主表、数主热、大主阳盛、滑主阳热壅遏，四者相合，既可主阳证之总纲，又可具体主热证、表证与实证。四类病机相互关联：阳证为总括，热证言其性质，表证言其病位，实证言其邪正关系，皆从不同角度说明浮大滑数脉所反映的阳气有余、邪气亢盛之病理状态，与阴脉所主之寒、虚、里证形成鲜明对照。", "c": [{"name": "主阳证", "desc": "浮大滑数脉象皆属阳，原文以「浮大滑数之类皆阳也」统括之。浮主表、大主阳热亢盛、滑主阳热壅盛、数主热，诸阳脉相合，故主阳证，与沉微细涩之阴证相对，为辨别阴阳之纲领。"}], "n": {"主阳证": 1}, "a": {"17483": "主阳证"}, "t": 1, "np": 0}, "c:弦+细+平+长": {"o": "弦细长平脉总以“弦细而长”为肝之常脉，主春季肝木平和之象。其病机分类皆以五行乘克为纲：若兼见他脏之脉，则示他脏乘肝。沉濡而滑为肾乘肝之虚邪，病轻易治；浮大而洪为心乘肝之实邪，病轻自愈；微涩而短为肺乘肝之贼邪，金克木而危重；大而缓为脾乘肝之微邪，病轻即瘥。诸类以肝平脉为基准，以兼脉定邪之虚实与预后，体现“脉以胃气为本”及五行生克思想。", "c": [{"name": "主肝平", "desc": "弦细而长为肝之常脉，主春季肝木旺而平和无病。原文以“脉弦细而长曰平”为纲，说明此脉是肝气条达、胃气充盛之象，非病脉。"}], "n": {"主肝平": 1}, "a": {"21430": "主肝平"}, "t": 1, "np": 0}, "pc:寸+细+小+紧+急": {"o": "寸·细小紧急脉总起来主血气不足、脏病寒凝及热郁。其脉细小，首主血少，因“脉小血少，病在心”“脉小血气俱少”，血虚脉道不充则细；其兼紧急，又主寒主痛，寒邪收引、气血凝滞则脉紧，且“脉迟在脏”提示病位在脏，脏病多寒；若兼滑疾，则“脉沉细滑疾者热”，为热郁伤阴、脉道拘急。四类病机以血少为本，寒凝、脏病、热郁为标，虚与寒、热相互兼夹，总属正虚邪扰、脉道拘急之候。", "c": [{"name": "主血少", "desc": "原文“脉小血少，病在心”，又“脉小血气俱少”，细小脉象反映血气不足，心主血脉，故寸脉细小紧急主心血亏少，血少则脉道不充，脉体细小。"}], "n": {"主血少": 1}, "a": {"21801": "主血少"}, "t": 1, "np": 0}, "c:大+浮+洪+长": {"o": "浮大洪长脉总起来主风邪外盛、阳热亢盛、气血涌盛及木亢金郁之病机。其脉浮大，主邪盛于外；洪长，主阳热有余、气血涌盛。诸类相互关联：风邪外袭可引动阳热，阳热亢盛则气血涌盛，气血涌盛又致木火亢盛而金气受抑。原文强调'中风发三秋，脉浮大而洪长'，秋令本应收敛，脉反浮大洪长，示风邪夹阳热亢盛、不得收敛之机，故以扶金汤抑木扶金、制其亢盛。四类病机以风邪为始动，阳热为核心，气血涌盛为表现，木亢金郁为脏腑失衡之结果，共同构成外风引动内热、气血壅盛、金木失和之证候。", "c": [{"name": "主风邪外盛", "desc": "脉浮大，浮主表、主外邪，大示邪气盛实。原文'中风发三秋，脉浮大而洪长'，浮大并见，说明风邪侵袭体表，邪盛于外，与秋令收敛相违，故主风邪外盛之病机。"}], "n": {"主风邪外盛": 1}, "a": {"22086": "主风邪外盛"}, "t": 1, "np": 0}, "c:数+弦+涩+紧": {"o": "紧数弦涩脉在原文中作为妇人‘不堪’之脉出现，总主气血失调、冲任失和，具体可析为气火偏亢与血少气滞两端。紧数主气火偏亢，弦涩主血少气滞，二者相合，则气血不调、冲任不盛，非孕育之佳兆。原文以‘求子先察母质’为论，列此脉为基址之忌，强调妇人以静厚重苍为贵，而紧数弦涩则属动、薄、涩之象，与‘贵静而贱动，贵重而贱薄’之旨相悖。三类病机相互关联：气火偏亢则血少，血少则气滞，气滞又化火，终致冲任失和。故临证见紧数弦涩，当虑气血失调、冲任不充，于子嗣之事尤须调治。", "c": [{"name": "主气火偏亢", "desc": "紧数之脉，紧为气机劲急，数为火热内盛，合而主气火偏亢。原文以‘紧数’并称，属‘不堪’之列，谓其非冲任充盛、气血调畅之象，故难孕育。气火偏亢则血海不宁，冲任失和，自非种子之基。"}], "n": {"主气火偏亢": 1}, "a": {"23791": "主气火偏亢"}, "t": 1, "np": 0}, "pc:六+数+滑+急+疾": {"o": "六·数滑急疾脉总属阳热实证，以火毒内炽为核心病机。滑主痰热内壅，数急疾主火势急迫，三者相合，反映痰、热、火毒交炽，充斥内外。原文所载纯阳无阴之证，见发热谵语、狂妄躁乱、大渴大烦、便秘溲赤，皆火毒炽盛、阳热有余之候。其病机可归纳为火毒炽盛、痰热内壅、阳热实证三类，三者相互关联：火毒为病之本，痰热为火毒所炼之病理产物，阳热实证则为火毒充斥之整体反映。脉象滑数急疾，正是痰热与火毒搏结、阳热亢盛之征，故治疗当以清热解毒为主，酌加化痰通腑之品。", "c": [{"name": "主火毒炽盛", "desc": "脉滑数急疾，滑主痰热内壅，数急疾主火势急迫。原文见发热谵语、狂妄躁乱、大渴大烦、便秘溲赤，断为火毒内炽，脉症相合，说明火毒充斥内外，故当清热解毒。"}], "n": {"主火毒炽盛": 1}, "a": {"23852": "主火毒炽盛"}, "t": 1, "np": 0}, "c:小+濡+缓": {"o": "小濡缓脉总起来主虚、湿、风三端，以脾肾亏虚为本，湿滞与肝风为标。小为气血不足或肾气亏虚，濡主湿滞，缓主脾虚或虚风不主流动。四段原文中，或见肾纳失司、肝风震突之右痪舌喑，或见脾虚湿滞之疟久痞满，或兼温热客气之耳后暴肿，皆不离虚中夹湿、虚风内动之机。其脉缓而不数，故非纯实热；濡小无力，故非纯外邪。各证之间，脾虚湿滞可致气血不足，肾虚肝风可兼湿热客气，总以正虚为本，湿、风、热为标，治多从补中益气、地黄饮子等扶正兼化湿熄风。", "c": [{"name": "主肾虚肝风", "desc": "脉小濡而缓，小为肾气不足，濡缓为虚风不主流动。原文见右痪、舌喑、足痱、头重、面戴阳、呵欠微呃，断为肾纳失司、肝风震突。肾脉萦舌本，虚风内动则舌下经脉涩滞，故舌强难言。"}, {"name": "主脾虚湿滞", "desc": "濡主湿，缓主脾虚，小弱为气血不足。原文见胸膈痞满、饮食少进、小便短赤、自汗，疟久经截药攻伐，脾胃受损，湿滞中焦。脉濡小而缓，右濡弱无力，正合脾虚湿恋、营卫不和之机。"}], "n": {"主肾虚肝风": 3, "主脾虚湿滞": 1}, "a": {"4418": "主肾虚肝风", "5005": "主肾虚肝风", "8552": "主肾虚肝风", "15080": "主脾虚湿滞"}, "t": 4, "np": 0}, "c:滑+沉+濡": {"o": "沉濡滑脉总起来主里湿痰积，兼及常脉与变证。其核心病机为湿浊痰积阻于里，沉主里、濡主湿、滑主痰，三者相合，故见寒湿积滞、痰湿内蕴等证；若兼数则化热，成痰热积滞；若为冬令肾脉，则沉濡滑为胃气与肾水相合之平脉，示无病之常。各类之间以‘湿痰积’为共同基础：寒湿、痰湿、痰热皆属邪实阻滞，惟兼寒兼热不同；平脉则属常象，与他脉相参可辨五脏乘克之邪。故本脉既主里实湿痰，又可为肾之平脉，常变之间须结合时令、兼脉及症候综合判断。", "c": [{"name": "主寒湿积滞", "desc": "沉主里，濡主湿，滑主痰积。原文谓‘寒积夹湿，交阻中宫，升降失度’，上吐下泻、指臂不温、舌苔淡黄而腻，正合寒湿积滞阻于中焦、阳气不达之机，故脉沉濡而滑主寒积夹湿、中宫格拒之霍乱。"}, {"name": "主痰湿内蕴", "desc": "沉主里，濡主湿，滑主痰湿。原文见伤寒误治后‘痰喘欲绝’，脉沉濡而滑相等，示痰湿内蕴、正气尚存；濡又主气血不足，故痰湿未化而正虚，尚可挽回，后脉缓和无力为气血渐复。"}, {"name": "色脉相参", "desc": "总论望色与切脉互参，以五脏应五色、五脉，察其相应与不相应，顺逆吉凶由内外相参而定，非专论沉濡滑一脉之病机。"}], "n": {"主寒湿积滞": 1, "主痰湿内蕴": 1, "色脉相参": 1}, "a": {"11185": "主寒湿积滞", "16392": "主痰湿内蕴", "18621": "色脉相参", "21110": "__np"}, "t": 4, "np": 1}, "c:弦+细+大": {"o": "细弦大脉总起来主虚实夹杂之证，以正虚为本、邪实为标。细弦多主阴血不足、中气虚或肝木失柔，大则主邪气壅盛，如风火、痰湿、暑湿等。三类具体脉象（弦大细弱、细弦洪大、弦细滑大）均体现由实转虚或虚中夹实的动态过程：或痰火风实为始、真水亏竭为本，或中气虚为本、肝郁痰滞为标，或心肾阴血不足为本、痰涎壅盛为标。各病机类别之间相互关联，风火亢盛、肝脾不调、暑湿蕴结等实邪可耗伤阴血，而正虚又易致邪气鸱张，形成本虚标实、虚实错杂的格局。", "c": [{"name": "主风火亢盛", "desc": "脉细弦转大，细弦为阴分稍复，转大乃火风鸱张之征。风火相煽，木旺克土，故见食入中脘作痛。此脉由细转大，示阴复而风火未熄，主风火亢盛、木贼土虚之病机。"}, {"name": "主肝脾不调", "desc": "脉弦右细左反大，弦为肝升太过，右细为脾虚不运，左大则肝木乘脾、气血壅滞。原文‘脾病肝升’点明土虚木贼，故见下痢不止、肠鸣肛痛、腹瘕攻撑，皆肝气横逆、脾络受伤之候。"}, {"name": "主暑湿蕴结", "desc": "脉右大左弦细，右大主暑湿蕴于气分、邪势鸱张，左弦细主阴分受灼、肝木失柔。暑湿内蕴，由单寒转疟，寒轻热盛，头重且胀，小溲浓赤，舌腻如粉，示邪实正伤、湿热交蒸之病机。"}], "n": {"主风火亢盛": 1, "主肝脾不调": 1, "主暑湿蕴结": 1}, "a": {"7242": "主风火亢盛", "9872": "主肝脾不调", "15580": "主暑湿蕴结"}, "t": 3, "np": 0}, "c:大+浮+疾": {"o": "浮大疾脉总属阳脉，主阳盛邪实、正气抗邪之候。其脉浮为病位偏表或阳气外浮，大为邪气壅盛或正邪交争，疾（数）为热盛或风邪急搏。三类病机相互关联：阳盛是其根本，邪实正抗是阳盛在伤寒温病中的具体表现，癫疾风搏则是阳盛风热挟痰上扰的变证。原文以浮大疾为阳脉，强调“阳病见阴脉者逆，阴病见阳脉者顺”，故浮大疾脉多主生、主顺，示正能抗邪；但若见于汗后津伤或沉小急疾，则又主死、主逆，须结合具体病证与兼脉判断。", "c": [{"name": "主阳盛", "desc": "浮、大、疾（数）皆属阳脉，原文列浮、大、数、动、长、滑为阳，并言“阳盛阴虚”则“浮之实大”，故浮大疾脉主阳热亢盛，邪气有余，正能抗邪之象。"}, {"name": "主邪实正抗", "desc": "伤寒热盛脉浮大者生，温病脉大疾者生，因热盛邪实而脉浮大疾，示正气尚能抗邪，邪有外达之机，故为顺证；若脉反沉小细微，则正不胜邪，主死。"}, {"name": "主癫疾风搏", "desc": "原文论五癫诊脉，谓“浮大附阴、牢疾皆癫”，脾脉紧而疾者癫脉，紧疾主风邪急搏，浮大疾脉示风阳上扰、痰气逆乱之癫疾，脉搏大滑者生，沉小急疾者不可疗。"}], "n": {"主阳盛": 1, "主邪实正抗": 1, "主癫疾风搏": 1}, "a": {"21811": "主阳盛", "21824": "主邪实正抗", "22103": "主癫疾风搏"}, "t": 3, "np": 0}, "c:弦+洪+缓": {"o": "弦洪缓脉总起来主风热内陷、气机郁滞、湿热内蕴与脾虚湿困四类病机，且常相互兼夹。其脉象弦洪缓相合而按之无力，弦在其上，洪缓并见，提示风热之邪内陷阴分，阳气不得宣通，同时肝郁气滞、湿热内蕴，进而困阻脾胃，导致气机升降失常。原文所载麻木、肢节烦疼、身体沉重、胸满短气、便溏或涩、痰嗽烦躁等症，皆由此数端交织而成。四类之中，风热内陷为始动因素，气机郁滞为关键环节，湿热内蕴与脾虚湿困为病理产物及转归，故治以调中益气汤等方，旨在升阳举陷、调畅气机、清化湿热、健脾和中。", "c": [{"name": "主风热内陷", "desc": "脉弦洪缓而按之无力，弦在其上，为风热下陷入阴中，阳道不行。原文见闭目则浑身麻木，昼减夜甚，开目则麻退，说明风热内陷、阳气不布，非外风为患。"}], "n": {"主风热内陷": 2}, "a": {"3918": "主风热内陷", "25192": "主风热内陷"}, "t": 2, "np": 0}, "c:大+散+乱": {"o": "大散乱脉总主元气离散、邪盛正衰之危候。其脉大而散乱，大则邪气盛而正气衰，散为元气离散，阴阳不相维系，故见大热、气促、汗多、昏愦等症，法在不治。然散乱非绝脉，属虚而可挽，原文以脉之敛散判预后吉凶，补后脉转收敛、喘缓泻减，说明散大之脉主元气欲脱，但非绝对死候。三类病机相互关联：元气离散为病本，邪盛正衰为病势，虚而可挽为转归，共同体现大散乱脉所主之危重证候及预后判断。", "c": [{"name": "主元气离散", "desc": "脉大而散乱，散为元气离散之象。原文谓“散为元气离散”，产后触怒，泄泻昏愦，大热汗多，气促，脉大左手散乱，乃元气欲脱、阴阳不相维系之危候，故众医谓法在不治。"}], "n": {"主元气离散": 2}, "a": {"6019": "主元气离散", "6313": "主元气离散"}, "t": 2, "np": 0}, "c:沉+濡+弱": {"o": "沉濡弱脉总属虚损之候，以气虚阳衰为核心病机。沉主里，濡弱主气虚阳衰，三者相合，揭示阳气虚衰、运化无力之本质。阳气不足，一则不能温煦脾土，致脾虚中满，症见胸膈痞胀、饮食少、大便溏泻；二则不能化气行水，致水湿内停，症见手足浮肿、身重不能动止；三则清阳不升、浊阴不降，形成虚实夹杂之候。原文患者多怒多欲，屡服消伐，更伤正气，故脉见沉濡弱。三类病机相互关联：气虚阳衰为根本，水湿内停与脾虚中满为由此衍生之标象，总以温阳益气、健脾化湿为治。", "c": [{"name": "主气虚阳衰", "desc": "脉沉而濡弱，濡弱为气虚阳衰之象。原文明言“濡弱主气虚阳衰”，患者年近六旬，多怒多欲，屡服消伐之品，致大便溏泻、手足浮肿、面黄且黑，皆脾阳不振、气虚不运之征，故脉见濡弱。"}], "n": {"主气虚阳衰": 2}, "a": {"5982": "主气虚阳衰", "6276": "主气虚阳衰"}, "t": 2, "np": 0}, "pc:左+数+滑+软": {"o": "左·数滑软脉总起来主正虚邪实、痰热内扰之证。滑主痰，数主热，软主虚，三象并见，提示痰热有余而正气已馁。具体而言，滑数反映痰热内盛，症见舌灰腻、口干咽燥、耳聋糊语、咳痰便闭；软则反映脏阴亏乏或营卫不足，故见寒热缠绵、正邪交争。两类病机相互交织：痰热灼阴则阴亏愈甚，阴亏正弱则痰热愈难清化，形成邪正交病、风波易起之势。临床当权衡虚实，既清痰热，又顾护阴液与营卫，不可偏执一端。", "c": [{"name": "主痰热", "desc": "脉滑主痰，数主热，滑数并见为痰热内盛之象。原文两段均以滑数为痰热有余，症见舌灰腻、口干咽燥、耳聋糊语、咳嗽痰白、便闭溲少，皆痰热蒙扰、灼伤阴液之征。"}], "n": {"主痰热": 2}, "a": {"9245": "主痰热", "9885": "主痰热"}, "t": 2, "np": 0}, "c:细+涩+和": {"o": "细涩和脉总起来主阴血亏耗、湿滞不畅、邪郁液亏及瘀血未尽等病机，其核心为阴液营血不足与邪滞内阻并存。细脉主阴血虚，涩脉主血行涩滞、湿阻或瘀血，二者相兼，多示正虚邪恋、虚实夹杂之候。各分类之间相互关联：阴血亏耗为根本，湿滞、邪郁、瘀血为标象，而脉象较和则反映营液渐复、病势向愈之转机。临床需结合具体症情，辨其虚损与邪滞之孰轻孰重，以判断预后及治法。", "c": [{"name": "主阴血亏耗", "desc": "细涩脉象主脏阴营液俱耗，阴亏血少。如原文'细涩本主脏阴营液俱耗'及'阴液已耗'，脉细为阴血不足，涩为血行不畅，故主阴血亏虚之病机。"}], "n": {"主阴血亏耗": 2}, "a": {"12487": "主阴血亏耗", "18586": "主阴血亏耗"}, "t": 2, "np": 0}, "pc:两+滑+虚+软": {"o": "两·滑虚软脉总起来主肺燥津伤、气阴两虚，兼风阳内煽。右脉软滑而虚，为肺伤于燥、治节不行、津液被烁之核心脉象；软虚并见，又示气阴两亏、上下交虚。左脉浮弦且数，则因辛甘温药致风阳内煽，为兼夹之变。三者相互关联：燥伤肺津为始因，津亏则气阴两虚，液亏则风阳易动；风阳内煽又进一步烁津耗液，形成恶性循环。故本脉所主非单纯痰嗽，而是燥、虚、风三者交织，治当保液息风、润燥扶正。", "c": [{"name": "主肺燥津伤", "desc": "右脉软滑而虚，为肺伤于燥、治节不行，津液被烁。原文谓‘病始肺伤于燥’，症见痰嗽、痰色清稀、舌素无苔、食不甘味，皆燥伤肺津、治节失司之征，故脉见软滑而虚。"}], "n": {"主肺燥津伤": 2}, "a": {"13364": "主肺燥津伤", "13890": "主肺燥津伤"}, "t": 2, "np": 0}, "c:弦+大+微": {"o": "大微弦脉总属虚损之候，以虚劳内伤、气血亏虚为根本。脉大为劳倦气虚、虚阳外浮，非邪实之象；微弦为土虚木乘、肝脾不和。三者相互关联：中气亏虚则气血不足，虚阳外浮而脉大；土虚则木乘，故见微弦。原文所载久患寒热、精遗自汗、能食神疲、肌肉渐瘦，正是虚劳中损、阴阳营卫失调、卫外不固之典型表现。故本脉总主虚劳、气虚阳浮与肝脾不和，治宜补中益气、调和营卫、收敛固涩，如黄耆建中加参、归、龙、牡之类。", "c": [{"name": "主虚劳", "desc": "脉大微弦，大为劳倦内伤、气血亏虚，非实大之象；微弦示虚中夹肝脾不和。原文见久患寒热、精遗自汗、能食神疲、肌肉渐瘦，显系中气亏虚、阴阳营卫失调之虚劳证，故脉主虚劳。"}], "n": {"主虚劳": 2}, "a": {"13423": "主虚劳", "13815": "主虚劳"}, "t": 2, "np": 0}, "c:数+微+急": {"o": "微数急脉总属正虚邪恋、阴虚内热之候。微脉主阳气衰微或正气不足，数急脉主邪热亢盛或里有热，二者相合，反映正气已虚而邪热未退，病情复杂。原文两段均强调'里有热'属阴虚，非关表邪，亦非湿热，故其病机核心为阴虚内热兼正虚。微数急脉所主病机可归纳为三类：一为阴虚内热，二为正虚邪恋，三为排除湿热实证。三者相互关联，阴虚内热是病机本质，正虚邪恋是病势特点，非湿热是鉴别要点。总以正虚为本，邪热为标，治当和中兼理脾肺，不可妄散其邪。", "c": [{"name": "主阴虚内热", "desc": "脉微数急，微为阳虚，数急为里有热，原文断为'里有热也'，且属阴虚里热。阴虚不能制阳，虚热内生，故脉数急而微，外皮不热而内有热，无头痛恶寒，非表邪所致。"}], "n": {"主阴虚内热": 2}, "a": {"13604": "主阴虚内热", "14716": "主阴虚内热"}, "t": 2, "np": 0}, "c:涩+缓+迟": {"o": "迟缓涩脉总属阳微血少、湿滞脉道之候，其病机可归纳为脾阳虚、营血耗、湿动中焦、阳盛伤阴及邪退正复五类。前两类常并见于久痢，脾阳失运则脉迟缓，营血耗伤则脉涩，湿动中焦更助缓象，三者相互关联，共成虚实夹杂之局。阳盛伤阴一类，脉虽缓小迟涩似虚寒，实由阳热灼阴、脉道不利所致，属危重证候。邪退正复一类，则见于痈疽脓溃后，微涩示邪衰，迟缓示正复，为向愈之征，但须防脉转沉细或洪数之变。诸类之间，以阳微血少、湿滞为共同基础，或偏虚寒，或偏阳盛，或主邪退，须结合具体脉象与证候辨析。", "c": [{"name": "主脾阳虚", "desc": "脉迟缓而涩，迟主阳微，缓主阳气弛缓，故主脾阳失运。原文见红痢日久，脾气虚，脉迟缓而涩，舌薄白，渴不贪饮，口恶甜味，皆脾阳失运之征。误服寒凉致痢复剧，更伤中阳，故脉象如此。"}], "n": {"主脾阳虚": 2}, "a": {"13569": "主脾阳虚", "14659": "主脾阳虚"}, "t": 2, "np": 0}, "pc:右+浮+洪+结": {"o": "右寸浮洪结脉，总起来主上焦热郁、气滞血瘀兼气血两伤之复合病机。浮洪为热郁于上，结为气滞血瘀，此二者反映邪实一面；余部沉细而软则为气血两伤，反映正虚一面。原文病案中，壮年患鼻齄，本多酒伤湿热，又久服苦寒驱风败血之剂，致‘虚其虚’之误：苦寒伤气耗血，风药燥胜伤血，故见倦怠、目不欲开；而右寸浮洪带结，正是上焦余热未清、气血瘀滞之象。三类病机相互关联：热郁可致血瘀，久服苦寒又伤气血，形成虚实夹杂之候。治宜化滞血、生新血，兼顾清热与补虚，不可一味苦寒攻伐。", "c": [{"name": "主热郁于上", "desc": "右寸浮洪，浮为阳浮于上，洪为热盛之象。原文谓‘浮洪为热郁于上’，结合鼻齄（酒齄鼻）多酒所伤、胸膈不利，可知热邪郁遏上焦，不得宣散，故脉浮洪见于寸部。"}], "n": {"主热郁于上": 1}, "a": {"3883": "主热郁于上"}, "t": 1, "np": 0}, "pc:六+沉+涩+小": {"o": "六脉沉涩小脉总起来主里实热结、瘀滞中焦，兼夹酒热暑湿。沉主里，涩主瘀滞，小主脉道收引，数主热，右甚则病在脾胃。患者好酒，暑途得疾，酒热与暑湿互结，瘀滞中焦，形成上脘块痛，故脉见沉涩小数目右甚，按之不为弱，说明里实热结而非虚证。治疗用大承气汤加减，通腑泄热，活血化瘀。各类病机相互关联，里实热结是根本，瘀滞是病理产物，酒热暑湿是诱因，共同构成沉涩小脉的复合病机。", "c": [{"name": "主里实热", "desc": "脉沉主里，数主热，右甚则热在脾胃。患者好酒，暑途得疾，上脘有块，牵引胁痛，乃酒热与暑湿互结，瘀滞中焦，故脉沉涩小数目右甚，按之不为弱，说明里实热结。"}], "n": {"主里实热": 1}, "a": {"3967": "主里实热"}, "t": 1, "np": 0}, "c:弦+大+实": {"o": "弦大实脉总属邪实正盛之象，其脉坚、弦、实、大并见，反映邪气亢盛而正气未衰，正邪交争剧烈。所主病机以邪实为核心，具体可分四类：邪实壅盛、痰积内阻、湿热蕴结、气滞不行。四者相互关联：厚味多怒致湿热内生，湿热酿痰，痰积壅塞气机，气滞又加重痰湿，形成邪实壅盛之局。脉弦主木郁，大实主邪盛，数主热，寸涩主气滞，诸象合参，提示邪实为主，兼夹痰、湿、热、气滞。在癫病卒忤中，见此脉者生，因邪实可攻，正未虚败；若脉虚伏濡小，则正衰邪陷，主死。故本脉预后判断关键在于正气盛衰，邪实而正不虚者，可攻可治。", "c": [{"name": "主邪实", "desc": "脉弦大颇实，大实主邪气亢盛，弦主木郁，数主热，反映邪实壅盛而正气未衰。原文以厚味多怒致湿热痰积，脉实大数示邪实，故主邪实病机。"}], "n": {"主邪实": 1}, "a": {"3929": "主邪实"}, "t": 1, "np": 0}, "pc:右+大+虚+空": {"o": "右·大虚空脉总属虚证，以阴血枯槁、阳气郁结为核心，进而导致胃气将败。其脉形大而空虚，非实热亢盛，乃阴血亏耗、脉道不充之征；兼细涩则阳气郁结、津血不充。原文见翻胃三月、粒米不存、面白神瘁、便燥，脉症合参已成膈症，胃气将败，预后不良。三类病机相互关联：阴血枯槁与阳气郁结并见，致中焦升降失司，终至胃气衰败。故本脉主虚损、郁结、胃败，总以正虚为本，病情深重。", "c": [{"name": "主阴血枯槁", "desc": "脉大空虚为阴血亏耗，脉道不充，虚大无力。原文见左脉大空虚，伴翻胃、粒米不存、面白神瘁、便燥，乃阴血枯槁之象，故主阴血虚竭。"}], "n": {"主阴血枯槁": 1}, "a": {"5022": "主阴血枯槁"}, "t": 1, "np": 0}, "c:数+细+急": {"o": "数细急脉总起来主虚火内炽、阴液亏耗、脏气不安之虚损证候。其核心病机为阴亏火旺，脉细为阴伤，数为虚火，急为脏气不安，三者相合，反映本虚标实、脏腑功能失调。此脉多见于虚损不复之候，如脾肺肾三脏并亏，脾失运化则生痰，肺失肃降则呛咳，肾失摄纳则气逆，诸症时轻时重。数细急脉所主诸类病机相互关联：阴亏为虚火之源，虚火为阴亏之标，脏气不安乃虚火扰脏、气机逆乱之果，而虚损不复则是诸机综合之结局。临证见此脉，当知病势缠绵，需缓图调治。", "c": [{"name": "主虚火", "desc": "脉数主热，细为阴亏，急为脏气不安，合为虚火内炽。原文'数为虚火，细为阴亏'明示阴液亏虚、虚火内生，火性急迫故脉数而急，阴血不足故脉细。此虚火非实热，乃本虚标实之象。"}], "n": {"主虚火": 1}, "a": {"7454": "主虚火"}, "t": 1, "np": 0}, "pc:左+弦+沉+涩": {"o": "左·弦沉涩脉总起来主肝血瘀滞、气郁湿阻及冲任不调。左脉涩主肝血瘀滞，右脉沉弦主气郁湿阻，二者相合，气血不畅，湿瘀互结，影响冲任带脉，故见带注腹痛有症、中脘胀闷背掣。三类病机相互关联：肝血瘀滞与气郁湿阻为病因，冲任不调为结果，共同构成气血湿瘀交阻之候，治宜顺气利中平肝。", "c": [{"name": "肝血瘀滞", "desc": "左脉涩为肝血瘀滞之征。原文'左脉涩'直接点明肝血瘀滞，涩脉主血行不畅，瘀血内阻，故见带注腹痛有症，冲任不调，带脉失约。"}], "n": {"肝血瘀滞": 1}, "a": {"17023": "肝血瘀滞"}, "t": 1, "np": 0}, "c:小+迟+短": {"o": "短小迟脉总起来主寒、主痛、主疝，三者相互关联。寒为根本，寒性收引凝滞，导致气血运行不畅，脉道拘急而现短小迟；寒凝气机不通则痛，故寒盛则痛；寒邪聚于下焦肝脉，则发为㿗疝，见小腹连卵肿急绞痛。原文指出“寒则脉当短小而迟”，又言“紧脉主痛，急为病甚”，说明短小迟脉虽以寒为主，但可兼见紧急之象，反映痛甚。因此，短小迟脉的核心病机是寒邪内盛，其变证为痛与疝，三者以寒为纲，痛与疝为寒之不同表现。", "c": [{"name": "主寒", "desc": "原文明确“寒则脉当短小而迟”，寒性收引拘缩，致小腹连卵肿急绞痛，脉象短小迟为寒邪内盛、阳气不达之征，故短小迟脉主寒。"}], "n": {"主寒": 1}, "a": {"19398": "主寒"}, "t": 1, "np": 0}, "pc:六+滑+沉+长": {"o": "六·滑沉长脉总起来主阳热、阴阳相兼及痰湿积滞。原文以浮、滑、长为阳脉，故滑长主阳热；又以沉滑、沉滑而长、浮滑而长时一沉分属一阴一阳、一阴二阳、一阴三阳，说明滑沉长脉可反映阴阳相兼之机，非单纯阳脉；沉主里，滑主痰，长主积，故沉滑而长又主里实痰湿积滞。三类之间，阳热为基本属性，阴阳相兼示其兼夹变化，痰湿积滞为具体病理产物，共同构成滑沉长脉所主病机的不同层次。", "c": [{"name": "主阳热", "desc": "原文以浮、滑、长为阳脉，滑脉往来流利，长脉过于本位，皆阳气有余之象。阳热内盛，气血涌盛，故脉道充盈流利而长，主阳热实证。"}], "n": {"主阳热": 1}, "a": {"21810": "主阳热"}, "t": 1, "np": 0}, "pc:尺+细+小+迟": {"o": "尺·细小迟脉总起来主正虚邪陷、津伤液竭及热盛正衰之危候。原文以脉之浮大沉小判伤寒温病吉凶：伤寒热盛脉浮大者生，沉小者死，因热盛邪实，脉浮大则邪有外达之机；已得汗则脉沉小者生，浮大者死，因汗后津伤，脉宜静敛。温病脉大疾者生，细小难得者死，示正能抗邪则生，正不胜邪则死。温病时行大热，其脉细小者死。可见细小之脉在热病中多主正虚邪陷、津液枯涸，正不胜邪，故为危候。三类病机相互关联：正虚则邪易内陷，津伤则脉道不充，热盛则更耗气阴，终致正衰邪陷之危。", "c": [{"name": "主正虚邪陷", "desc": "原文以脉之浮大沉小判伤寒温病吉凶：伤寒热盛脉浮大者生，沉小者死，因热盛邪实，脉浮大则邪有外达之机；已得汗则脉沉小者生，浮大者死，因汗后津伤，脉宜静敛。温病脉大疾者生，细小难得者死，示正能抗邪则生，正不胜邪则死。"}], "n": {"主正虚邪陷": 1}, "a": {"21824": "主正虚邪陷"}, "t": 1, "np": 0}, "c:濡+缓+软": {"o": "缓濡软脉总属虚证，以阳气虚、气虚为核心病机，尤与肺脏虚损密切相关。脉缓为阳气弛缓，濡软为鼓动无力，故主阳气不足、气虚不充。原文以肺虚腹胀为例，明言“肺阳不足，脉缓濡软”，并指出与肺阴虚之“虚细数”、气散之“散”脉相鉴别，强调此脉为阳气虚而非阴亏。三类病机相互关联：阳虚必兼气虚，气虚可致肺虚，肺虚又易累及阳气。因此，缓濡软脉总体反映机体功能减退、阳气虚弱，治当温补阳气、益气补肺，忌用寒凉滋腻。", "c": [{"name": "主阳虚", "desc": "脉缓濡软为阳气不足之象。原文明确指出“肺阳不足，脉缓濡软”，缓为阳气弛缓，濡软为阳气不能鼓动，故脉道软弱无力。此脉象直接反映阳气虚衰，不能温煦推动，治以四君子汤、补中益气汤温补阳气。"}], "n": {"主阳虚": 1}, "a": {"24882": "主阳虚"}, "t": 1, "np": 0}, "pc:右+弦+沉+和": {"o": "右·弦沉和脉总起来主风气腹痛之病机，以脉象分表里寒热。浮缓主风邪在表，沉弦主邪郁于里，迟主中焦虚寒。各类之间以表里为纲，风邪外袭与里气不和相互关联，虚寒则为本虚标实之变。临证凭脉之浮沉迟弦，分表里用药，体现了脉诊在风气腹痛辨治中的核心作用。", "c": [{"name": "主风邪在表", "desc": "原文'脉浮缓者祛风'及'寒热脉浮，防风汤'，浮脉主表，缓为风象，风邪袭表故见浮缓，治当祛风解表。"}], "n": {"主风邪在表": 1}, "a": {"25058": "主风邪在表"}, "t": 1, "np": 0}, "pc:右+细+虚": {"o": "右·细虚脉总属正气亏虚之象，以气阴两虚、营血不足、脾胃气虚为核心，脉道不充故细而无力。虚细常兼数、弦、滑等，兼数则示虚热内扰或阴亏阳亢；兼弦则示肝木偏旺、乘犯脾土；兼滑数或洪大则示正虚而湿热、暑湿、相火等邪内蕴，形成虚实夹杂之候。各类病机相互关联：气阴亏虚为本，可生虚热，可致肝木失养而横逆，可因脾虚运化失职而湿浊内停，湿郁化热则邪恋不去。故右细虚脉所主，总以虚损为基础，或纯虚，或虚中挟实，须结合兼脉及症候辨其虚之所在与邪之性质。", "c": [{"name": "主气阴两虚", "desc": "右脉虚细为气阴不足之象。原文如“克削过甚，津液元气俱伤”，“阴气大亏”，“气阴不足”，皆见虚细脉伴舌燥、汗出、咳喘等，故主气阴耗伤。"}, {"name": "主营血亏虚", "desc": "虚细主营血亏少，脉道不充。如经漏淋沥、血不养肝，阴伤劳瘵，肾阴亏虚，均见右脉虚细，说明阴血耗损、血不荣脉。"}, {"name": "主肝木犯土", "desc": "右脉虚细而左关弦，为肝气偏旺、木乘土位。如“肝木偏横”，“胃被肝乘”，左弦右细，见脘闷、便泻，故主肝郁乘脾、胃弱不运。"}], "n": {"主气阴两虚": 6, "主营血亏虚": 1, "主肝木犯土": 2}, "a": {"758": "主气阴两虚", "10544": "主营血亏虚", "10870": "主气阴两虚", "12829": "主气阴两虚", "14835": "主气阴两虚", "14854": "主气阴两虚", "16878": "主气阴两虚", "16998": "主肝木犯土", "16999": "主肝木犯土"}, "t": 9, "np": 0}, "c:涩+紧": {"o": "紧涩脉总起来主寒凝、血瘀、气滞、正虚诸端，其核心病机为寒邪凝滞、气血不畅。紧主寒主痛，涩主血瘀气滞，二者相合，多示寒凝血瘀、气机壅塞之证。从所主病机看，或为寒伤营血、瘀阻下焦，或为寒湿内郁、脾运失职，或为本虚标实、气滞血涩，或为气血壅滞、脉道不利，或为风寒湿杂合痹阻，或为胃反难治之正虚邪结。各类之间相互关联，总以寒凝气滞血瘀为共同基础，兼见正虚、湿阻、热毒等不同兼夹。脉紧涩者，提示病机较深，气血运行受阻，预后多需结合具体脉位与兼脉判断。", "c": [{"name": "主寒凝血瘀", "desc": "紧主寒，涩主血瘀，紧涩相合，寒邪凝滞血脉，血行不畅。如两尺脉紧而涩，知寒伤营血，经期饮冷致血凝，瘀阻大肠而痢下黄黑、痛而急迫；又如脉紧涩，知冷药利水太过，阴气独降，阳气不升，寒凝气滞而梦遗。"}, {"name": "主本虚标实", "desc": "虚紧涩脉主本虚标实、气滞血涩。虚脉揭示脾胃气伤、正气不足之本；紧脉提示气机壅滞、升降失常之标；涩脉反映血行不畅、脉道不利之兼症。常见于忧思过度、情志所伤致脾胃气结、气血失和之候。"}, {"name": "主胃反难治", "desc": "趺阳脉紧而涩，紧主寒凝，涩主脾伤血少，寒结而脾阴耗，胃气上逆不通，宿谷不化，朝食暮吐、暮食朝吐，名为胃反。正虚邪结，故其病难治。此以紧涩判胃反之预后不良。"}], "n": {"主寒凝血瘀": 2, "主本虚标实": 2, "主胃反难治": 4}, "a": {"3496": "主寒凝血瘀", "3497": "主寒凝血瘀", "8425": "主胃反难治", "18412": "主本虚标实", "21591": "主胃反难治", "23317": "主胃反难治", "25407": "主胃反难治", "27102": "主本虚标实"}, "t": 8, "np": 0}, "c:濡+迟": {"o": "濡迟脉总以寒湿内蕴、阳气虚衰为核心病机。濡主湿，迟主寒，二者相合，反映寒湿困阻、阳气不运之象。其具体所主，可因兼脉与部位而异：兼浮则表虚湿滞，兼沉则大气下陷，兼数则邪伏热结，兼虚则中阳不足。然究其根本，总不离阳虚与湿滞两端：阳虚则寒生，湿滞则气机不利，故脉来迟而濡。各病机之间相互关联，寒湿内蕴可致阳虚气弱，阳虚气弱又可生寒痰闭阻，甚则中气下陷；而表虚湿滞、邪伏热结则为兼夹之变。临证当结合兼脉、部位及症候，辨其寒湿、阳虚、痰闭、气陷之侧重，以温阳化湿、健脾益气为要。", "c": [{"name": "主寒湿内蕴", "desc": "濡主湿，迟主寒，合为寒湿之象。原文如“濡为太阴里湿弥漫，迟为太阳表邪郁遏”，“濡主湿浊内蕴，迟主寒与阳气不运”，“右脉濡迟，太阴寒湿；左脉濡迟，少阴寒湿”，皆示寒湿困阻中焦或脾肾，气化不利。"}, {"name": "主阳虚气弱", "desc": "迟为阳衰，濡为气弱不鼓。如“濡迟为阳气式微”，“迟主寒、濡主阳虚湿滞”，“迟濡之脉说明寒湿内盛、阳气不伸”。阳气虚馁，运化无力，故脉来迟而软弱，主脾肾阳虚、命火式微。"}, {"name": "主寒痰闭阻", "desc": "寒湿内盛，聚液成痰，闭阻经络。如童子身挺搐搦，脉甚迟濡，断为“寒痰凝结、瘀塞经络”；呕吐涎沫，脉迟濡，为“寒饮内停”。迟主寒，濡主湿，寒痰湿浊阻滞气机，蒙蔽清窍或壅塞经络。"}, {"name": "主中气下陷", "desc": "沉濡迟脉主大气下陷，如总述“沉为气虚不升，濡为气弱不鼓，迟为阳运无力”；“阳陷入阴，命火式微”亦示中气下陷、清阳不升。气虚无力升举，故脉沉而濡迟，伴便溏、纳少、气短等症。"}, {"name": "主表虚湿滞", "desc": "浮迟濡脉主表虚、阳弱、湿滞。如总述“浮为表虚，卫外不固则汗多；迟为阳弱，阳气不足则神倦；濡为湿滞，脾虚不运则痰湿内生”。此脉多见于热退邪余之际，正气未复，表虚不固，痰湿留恋。"}], "n": {"主寒湿内蕴": 3, "主阳虚气弱": 1, "主寒痰闭阻": 1, "主中气下陷": 1, "主表虚湿滞": 1}, "a": {"118": "主表虚湿滞", "269": "主中气下陷", "474": "主寒湿内蕴", "2186": "主阳虚气弱", "19462": "主寒湿内蕴", "19575": "主寒痰闭阻", "25093": "主寒湿内蕴"}, "t": 7, "np": 0}, "pc:右+小+濡": {"o": "右·小濡脉总起来主脾虚湿滞、气血亏虚，兼及湿痰、暑湿、土虚木乘等病机。小为气虚，濡为湿滞，右脉候脾肺，故其核心为脾虚湿困、气血不足。各段原文或见劳倦伤脾、风湿外袭，或见暑湿伤气、痰湿内阻，或见土虚木乘、气不摄血，皆以正虚为本、湿滞为标。滑小濡脉偏于湿痰留恋，小濡缓脉偏于脾虚湿滞，而总不离中焦虚弱、湿浊内停之格局。诸类之间，脾虚湿滞为基本病机，气血亏虚为虚损之渐，湿痰、暑湿为兼夹之邪，土虚木乘为脏腑相克之变，临证当以扶脾化湿为主，兼顾他邪。", "c": [{"name": "主脾虚湿滞", "desc": "右脉小濡，小为气虚，濡为脾弱湿滞。原文见不饥、便溏、神倦嗜卧、少纳、胸痞等症，皆脾虚失运、湿浊内困之候。劳倦伤脾、暑湿伤气亦致此脉，故主脾虚湿滞。"}, {"name": "主气血亏虚", "desc": "小脉主正虚，濡脉亦见于气血不足。原文见右细耎无力、左寸涩、尺濡小，症见咳血、颧红、白淫绵绵，为脾肺气虚、阴亏阳弱、气血失和之象，故主气血亏虚。"}, {"name": "主暑湿伤气", "desc": "濡主湿，小主气弱。原文谓体肥中气必弱，暑湿伤气分，症见鼻窍霉黑、胸痞烦闷、舌苔灰霉、渴饮脘痞，右脉濡小为暑湿内伏、气分受困之象，故主暑湿伤气。"}, {"name": "主土虚木乘", "desc": "右脉浮虚颇弦，虚为脾肺气虚，弦为土虚木乘。原文见伤饥雨湿、食冷呕吐、胃脘痛、吐瘀血、便溏、惊惕，皆脾胃虚寒、肝气犯胃、气不摄血，故主土虚木乘。"}], "n": {"主脾虚湿滞": 3, "主气血亏虚": 1, "主暑湿伤气": 1, "主土虚木乘": 1}, "a": {"1437": "主脾虚湿滞", "5809": "主脾虚湿滞", "10660": "主脾虚湿滞", "11102": "主暑湿伤气", "15157": "主土虚木乘", "15942": "主气血亏虚"}, "t": 6, "np": 0}, "c:大+弱": {"o": "大弱脉总以虚为本，然所主病机有气血两虚、气虚痰湿、热郁血虚及阴阳乖违数端。其脉象大而弱，大则示虚，弱为气衰，故虚证居多，如气血不足、心气虚弱、脾虚痰湿等。然虚中每夹实邪，如酒热内郁、痰湿内蕴，则脉见大弱而兼实涩或滑数，此乃正虚邪恋之候。又有上下阴阳乖违者，右大左弱，上热下寒，亦属大弱脉之变。诸类之间，总因正气不足，或气血亏耗，或气不运湿，或虚而受邪，或阴阳不交，故临床当脉症合参，辨其虚之所在与邪之有无，不可一概而论。", "c": [{"name": "主气血两虚", "desc": "脉大而弱，大则为虚，弱为气血不足，如两寸关脉大而弱，两尺涩小，断为气血不足大虚之证；脉微弱无力系心气虚，数滑为血虚有热，皆心体虚弱所致。故大弱脉主气血亏虚，尤以心脾两虚为要。"}, {"name": "主热郁血虚", "desc": "脉大而弱，右关稍实略数，重取则涩，为酒热内郁、血虚热郁之象。如形瘦色黑喜酒之人，大恶寒发战、渴不饮，脉大弱中见实涩，乃热郁不得外泄，非纯虚可补，故主热郁血虚。"}, {"name": "主阴阳乖违", "desc": "脉右大左弱，右大主上部火升，左弱主下焦虚冷，如经水紫黑、嘈杂、脉络收引而痛、带下不断、形瘦日减、下焦冷彻骨中，乃阴阳乖违、阳不交阴之候，故大弱脉亦主上下阴阳不相交通。"}], "n": {"主气血两虚": 1, "主热郁血虚": 4, "主阴阳乖违": 1}, "a": {"1722": "主阴阳乖违", "3595": "主热郁血虚", "15300": "主热郁血虚", "18340": "主气血两虚", "20188": "主热郁血虚", "24308": "主热郁血虚"}, "t": 6, "np": 0}, "pc:左+涩+芤": {"o": "左·涩芤脉总起来主血虚与血瘀并见之病机。芤脉中空，主营血虚少、脉道不充；涩脉滞涩，主血行瘀滞、脉络不畅。二者相合，既可因营血亏虚而脉络失养，出现筋挛掣痛（如1653段）；又可因瘀血内阻而血不循经，出现似虚实实之候（如4099、4100、4338段之胞络积血，24870段之蓄血）。各类之间以“血”为核心：血虚为本，血瘀为标，虚可致滞，瘀可致虚，故芤涩并见常提示虚实夹杂。临证须结合神色、病史及兼脉，辨其偏虚偏瘀，不可一见芤涩即投补益，亦不可一味攻破。", "c": [{"name": "主血虚", "desc": "芤脉中空，主营血虚少，脉道不充。原文如1653段“左脉忽现芤涩”，释为“芤主营血虚而脉道不充”；4099段“芤主血虚失血”；4338段“芤主血虚”。故芤涩并见，首先提示营血亏虚，脉络失养。"}, {"name": "主蓄血", "desc": "24870段论伤寒腹胀，两尺沉牢为蓄血，血结在阴而脉反芤涩。芤为血虚、涩为血滞，示瘀血内结而血不循经。虽以沉实牢数为主，但芤涩并见提示蓄血内结，血行不畅。"}], "n": {"主血虚": 1, "主蓄血": 4}, "a": {"1653": "主血虚", "4099": "主蓄血", "4100": "主蓄血", "4338": "主蓄血", "24870": "主蓄血"}, "t": 5, "np": 0}, "c:涩+软": {"o": "软涩脉总属虚实夹杂之候，以虚为本，以滞为标。软为气虚不充、阳气式微或湿邪内盛，涩为血少气滞、脉道不利。所主病机可归纳为虚、滞、热、湿、郁、暑六类：虚为气血阴阳亏虚，滞为气滞血瘀，热为热伏于内，湿为湿阻气机，郁为肝郁气逆，暑为暑湿外侵。诸类之间，虚为根本，因虚而致气滞、湿停、血涩，进而化热、郁而化火，或外邪乘虚而入。原文叶承恩案脉软涩不鼓指而断为真阴素亏、热伏于内，西甫案脉涩滞而断为伏暑晚发、本元极亏，季杰弟案脉软以涩而断为肝郁于内、暑侵其外，皆示软涩脉非纯虚纯实，须结合舌症辨其虚实寒热。下属软大涩、细软涩、虚软涩、小软涩、缓软涩、沉涩软诸脉，总不离气血亏虚、中阳式微、气滞血涩、湿停痰饮之机，而各有偏重。", "c": [{"name": "主热伏", "desc": "软涩不鼓指非独虚寒，亦可为热郁气机、脉道不利。原文叶承恩案脉软涩而不鼓指，右手尤甚，宛似虚寒，然舌紫苔黄腻口苦、眼鼻出火，断为真阴素亏而热伏于内。热郁则脉不鼓指，软涩为热伏气滞之象。"}, {"name": "主肝郁", "desc": "软为气虚，涩为郁滞血少，肝郁气逆则脉道不利。原文季杰弟案脉软以涩，断为肝郁于内、暑侵其外，症见疟日轻夜重、少腹块上冲、呕嗽并作。沉涩软脉兼弱亦主郁怒伤肝、肝营亏虚、气逆痰升。"}, {"name": "主暑湿外侵", "desc": "软涩脉示正虚郁滞，暑湿外袭则气机受阻。原文季杰弟案脉软以涩为肝郁于内、暑侵其外，疟发日轻夜重；西甫案脉形涩滞为伏暑晚发而本元极亏，继脉软涩为邪未尽而正已伤，皆暑湿外侵兼正虚之候。"}], "n": {"主热伏": 2, "主肝郁": 1, "主暑湿外侵": 2}, "a": {"13080": "主热伏", "13098": "主暑湿外侵", "13190": "主肝郁", "13927": "主热伏", "13931": "主暑湿外侵"}, "t": 5, "np": 0}, "pc:右+滑+软": {"o": "右·滑软脉总起来主湿、痰、虚三端，以脾肺为中心。滑主湿盛痰凝，软主气虚阳弱，右脉候脾肺，故其病机多归脾虚失运、湿痰内蕴，或肺实痰壅、气逆不降。四段中，或纯为湿痰内蕴（案5），或脾虚湿盛水泛（案15627），或肺实痰壅兼肾虚（案2124），或虚中夹滞、肝脾不和（案9812）。要之，滑软并见，虚中夹实，以脾虚为本、湿痰为标，病位在脾肺，涉及肝肾。各段虽侧重不同，然皆不离“正虚湿滞”之总机，治当健脾化湿、疏肝理气，兼顾虚实。", "c": [{"name": "主湿痰内蕴", "desc": "右脉滑软，滑主湿盛痰凝，软主脾虚不运。如案5“软滑主湿痰内蕴”，湿痰阻于中焦，见痞闷、不思饮食；案9812右滑为脾胃湿滞、痰食内蕴，二便不畅。皆因脾虚失运，湿聚成痰，痰湿内阻而脉见滑软。"}, {"name": "主脾虚湿盛", "desc": "右脉候脾，软为脾虚，滑为湿盛。案15627“软主脾虚，滑主湿盛”，两足浮肿，朝退夕肿，乃脾虚不能运化水湿，湿邪下注。脉软滑示湿浊内蕴而正气已虚，脾土日衰，水湿泛溢，甚则成中满。"}, {"name": "主肺实痰壅", "desc": "右寸候肺，滑软为痰气壅实。案2124喘症“在肺为实”，右寸滑软，左脉细涩，肺肾并衰，出纳无权。滑软示肺中痰气壅实，痰色瘀紫，亦气馁少液之征，脉象合虚实夹杂之机。"}, {"name": "主虚中夹滞", "desc": "右滑软与左软并见，软为正气偏虚，滑为湿滞内蕴。案9812病后腹痛，右半硬，二便不畅，脉左软右滑，说明肝脾不和，脾运失健则湿滞右半而硬，气机不畅则二便不利。软滑并见，虚中夹滞，治在肝脾。"}], "n": {"主湿痰内蕴": 1, "主脾虚湿盛": 1, "主肺实痰壅": 1, "主虚中夹滞": 1}, "a": {"2124": "主肺实痰壅", "4664": "主湿痰内蕴", "9812": "主虚中夹滞", "15627": "主脾虚湿盛"}, "t": 4, "np": 0}, "pc:右+虚+实": {"o": "右·虚实脉总以虚实夹杂、正虚邪恋为纲。其脉象或微数无伦次如虾游，或弦细芤迟，或软小濡小与滑数并见，皆提示正气亏虚而邪气内郁。所主病机主要有正虚邪陷、虚实夹杂、阴血亏虚、暑邪内郁四类。正虚邪陷为危重之候，多见于瘟疫、久病误治，脉失根本；虚实夹杂常见于痰火喘咳，气火虚而痰火实；阴血亏虚与暑邪内郁则多见于年高体弱、暑邪内迫之证，脉虚而证实。四类之间相互关联，总因正虚不能胜邪，邪气内陷或郁而化热，形成虚中夹实、实中见虚之局，故诊治需权衡虚实缓急，扶正祛邪并施。", "c": [{"name": "主正虚邪陷", "desc": "脉见微数无伦次或弦细芤迟，为正气虚衰而邪气内陷。如瘟疫经水适来，里虚邪陷，脉微数无伦次如虾游，乃胃气衰败、正气欲脱；或年高久病，误补致邪盛正虚，脉弦细芤迟，示阴血亏虚而暑邪内郁。"}, {"name": "主虚实夹杂", "desc": "脉象软小濡小与滑数并见，为气火虚而痰火实。如喘咳有年，右寸软小不疏、关滑数、左尺濡小按之无力，软小濡小为气火虚，滑数为痰火实，虚实夹杂，痰火不易出，治当分清虚实缓急。"}, {"name": "主暑邪内郁", "desc": "脉弦主暑邪内郁。如吸受暑邪，误作虚治，右脉弦细芤迟，弦为暑邪内郁之象，细芤迟为阴血亏虚，邪愈盛而正反虚，故见口渴溲涩、面赤自汗等暑热内迫之症。"}], "n": {"主正虚邪陷": 1, "主虚实夹杂": 1, "主暑邪内郁": 2}, "a": {"3384": "主正虚邪陷", "13202": "主暑邪内郁", "14393": "主暑邪内郁", "15518": "主虚实夹杂"}, "t": 4, "np": 0}, "pc:右+浮+虚": {"o": "右·浮虚脉总主气虚不固，以脾肺气虚为核心，兼及血虚、卫虚、土虚木乘。浮为气浮于外，虚为鼓动无力，故诸段皆见气不内守、正气不足之象。其类可分：气虚、脾肺虚、血虚、卫虚风动、土虚木乘。气虚为总纲，脾肺虚为病位所在，血虚为气不摄血之果，卫虚风动为表气不固之变，土虚木乘为虚中夹实之兼。诸类相互关联，总由气血虚衰、中气不固所致，故脉变动无常，症见畏寒、倦卧、声哑、食少、便溏、风疹等。", "c": [{"name": "主气虚", "desc": "右脉浮虚无力，按不应指，为气不内守、鼓动无力之象。原文见“右脉浮软无力”“心肺脉浮虚按不应指”，并谓“脉不常，血气虚也”，故主元气不足、中气不固，症见倦卧、畏寒、声哑、食难消等。"}, {"name": "主卫虚风动", "desc": "右寸虚浮主卫气不固，易冒外风；营血不充则血热生风。原文“右寸虚浮……虚浮为卫气不固”，外风与内风相召，症见肤热痛痒、风疹随起，治宜固表养血。"}, {"name": "主土虚木乘", "desc": "右浮虚颇弦，为脾土虚而肝木乘之。原文“弦为土虚木乘”，症见胃脘痛、呕吐、惊惕，脉象示中虚木乘、气血失和，乃脾胃虚寒、肝气犯胃之病机。"}], "n": {"主气虚": 2, "主卫虚风动": 1, "主土虚木乘": 1}, "a": {"3615": "主气虚", "15157": "主土虚木乘", "15216": "主气虚", "15480": "主卫虚风动"}, "t": 4, "np": 0}, "pc:右+细+空": {"o": "右·细空脉总起来主精伤气散、阴血亏虚与邪滞气逆三类病机。脉细为阴血不足，空为气不摄固或营阴亏虚，二者并见，多示正虚之候。若兼色夺神夭、声嘶、咳汗，则属精伤于下、气不摄固之劳怯重病；若见麻痹、困倦、便溏黑，则偏于阴血亏虚、虚风内动。然虚中常夹实，右脉弦急则提示湿痰瘀血等邪滞未化、气机逆乱，形成虚实夹杂之局。三类之间，正虚为本，邪滞为标，虚波暗起，气不平则诸症难解，故临床须细辨虚损与邪滞之轻重。", "c": [{"name": "主精伤气散", "desc": "右脉空为气不摄固，左脉细为精血亏少，合之色夺神夭、声嘶、咳汗，显系下焦精伤、上焦气耗。精伤则咳，气不固则汗，劳怯重病由此而成，故脉细主阴亏，空主气散。"}, {"name": "主阴血亏虚", "desc": "脉细主阴血不足，空为营阴亏虚，左脉空细或细空，反映阴血亏虚，不能涵养。原文见麻痹、神情困倦、大便溏黑等，皆阴血亏虚之象，虚波暗起可虑。"}], "n": {"主精伤气散": 1, "主阴血亏虚": 2}, "a": {"824": "主精伤气散", "4673": "主阴血亏虚", "9098": "主阴血亏虚"}, "t": 3, "np": 0}, "c:涩+伏": {"o": "涩伏脉总起来主气机郁滞、气闭不通，兼及血瘀、阳损与脏虚。其脉涩主血滞，伏主气闭，左脉候血，故常见于郁怒伤肝、气机壅塞之证，症见胸脘痛极、昏厥、四肢逆冷；气闭则脉沉涩似伏，气复返则苏。若积劳损阳，阳气亏虚，血行瘀滞，亦见涩伏，伴下瘀血不止、舌白不食，预后难治。此外，脏虚者脉按之沉小微弱短涩软濡，涩伏亦为正气内衰之象。各类之间，气郁血滞与气闭昏厥常相因，气闭可致血瘀，血瘀加重气滞；积劳损阳与脏虚则属虚证，阳气不足推动无力，血行涩滞，脉道不充，故涩伏并见。总以气机闭阻、血行不畅为关键，虚实夹杂，须结合兼脉及症候辨析。", "c": [{"name": "主气郁血滞", "desc": "涩主血滞，伏主气郁，左脉候血。原文见左涩伏，因惊起怫郁，气机逆乱，血行不畅，故脉涩伏；伴呕吐脘痛引胁、痛甚四肢冷麻，揭示肝郁气滞、血瘀络阻之病机。"}, {"name": "主积劳损阳", "desc": "涩伏脉见于积劳损阳，阳气亏虚，推动无力，血行瘀滞。原文谓“积劳损阳”，曾下瘀血延绵不止，伴舌白不能食谷，乃阳损血滞、瘀血内阻之象，故脉涩伏而预后难治。"}, {"name": "主脏虚", "desc": "华元化论脏虚，诊脉“按之沉小微弱短涩软濡，俱为脏虚”。涩伏脉按之沉涩似伏，属正气内衰、根本不足之象，故主五脏之虚，伴肠鸣气走、足冷手寒、食不入胃等虚候。"}], "n": {"主气郁血滞": 1, "主积劳损阳": 1, "主脏虚": 1}, "a": {"1621": "主积劳损阳", "8600": "主气郁血滞", "22693": "主脏虚"}, "t": 3, "np": 0}, "pc:尺+微+缓": {"o": "尺部微缓脉在本案中总主气血两亏、正虚邪恋之候。三则原文均以'尺寸脉俱微缓'与'泄痢一载，气血两亏'并见，可知微缓为下焦元气虚衰、气血双损之象。然此虚非单纯之虚，乃痰积、湿热、肝气交阻日久，耗伤气血所致，故脉象又寓正虚邪恋、攻补两难之意。微主阳气衰微，缓主正气不足，合而观之，既示脾肾气弱、运化无力，又示湿浊内滞、积结难拔。三类病机相互关联：气血两亏为其本，正虚邪恋为其势，脾虚湿滞为其机，总属本虚标实、虚实夹杂之候。", "c": [{"name": "主气血两亏", "desc": "原文三处均言'尺寸脉俱微缓，泄痢一载，气血两亏'。微为阳气衰微，缓为正气不足，尺寸俱见微缓，说明下焦元气亏虚，气血双损，故脉来微弱而弛缓，主久痢耗伤、气血两亏之虚证。"}], "n": {"主气血两亏": 3}, "a": {"10858": "主气血两亏", "13666": "主气血两亏", "14781": "主气血两亏"}, "t": 3, "np": 0}, "pc:左+大+实": {"o": "左·大实脉总以邪热壅盛为核心病机。实主邪盛，大主热，左脉候肝胆，故其主病多与肝胆火旺、风温上扰、上焦壅热相关。原文1271明言风温仍在上焦，清窍被蒙，实大之脉示温邪壅盛、肝胆之火上扰、气机升降失司；原文19361论心脉太过令人身热骨痛、口疮舌焦，亦属热盛之候。可见大实脉所主，一为外感温邪壅盛于上焦，二为内生火热亢盛，三为心火太过、热淫于外。诸类之间，总由邪热炽盛、气血涌盛所致，病位偏上偏外，属实热之象，治当清解升降，使邪热得清，气机自利。", "c": [{"name": "主热", "desc": "大脉主热，实大之脉尤显热盛。原文1271言“实主邪盛，大主热”，左脉候肝胆，风温之邪壅盛于上，肝胆之火上扰清窍，故见头目如蒙、清窍不爽。热邪亢盛，气血涌盛，脉道充盈，故脉形大而实。"}], "n": {"主热": 2}, "a": {"1271": "主热", "19361": "主热"}, "t": 2, "np": 0}, "pc:关+浮+空": {"o": "关·浮空脉总属虚证，以气虚为核心，兼涉内伤虚损与阴亏气弱。浮为气浮于外，空为内虚不实，故非表邪实滞。原文一者因努挣伤气、阴乘阳位而见寸脉浮空，关尺微细，属内伤虚损、阴阳失调；二者直述“浮则为气，空则为虚”，分列五脏气弱，总归气虚眩晕。三类相互关联：气虚为根本，内伤虚损为成因，阴亏气弱为兼夹，皆示正气不足、脏腑功能衰退之机。", "c": [{"name": "主气虚", "desc": "脉浮而空，浮为气浮于外，空为内虚不实。原文谓“浮则为气，空则为虚”，且分述右寸肺气不足、右关中气不足、左寸心气不足、左关肝胆气弱、两尺肾气不足，诸部皆虚，总属气虚，故主气虚眩晕、气短乏力等症。"}], "n": {"主气虚": 2}, "a": {"3450": "主气虚", "24801": "主气虚"}, "t": 2, "np": 0}, "pc:关+弱+软": {"o": "关·弱软脉总起来主脾胃气虚，并常提示虚实夹杂。右关候脾胃，脉来软弱无力，是脾胃气弱、鼓动不足之征，故凡见右脉软弱，多责之中气已伤，运化无力。然软弱之象并非单纯虚证，原文中与左脉数而有力并见，症见发热、口渴、舌干、便下热不除，形成邪热内盛与脾胃气弱共存的局面，说明软弱脉可在邪实背景下出现，反映虚实夹杂。因此，该脉所主病机以脾胃气虚为核心，同时涵盖虚象与实邪并存的复杂状态。两类之间，脾胃气虚是基础，虚实夹杂是在此基础上兼见邪实，临证当顾护脾胃，不可一味攻伐，亦需行气通腑以祛实。", "c": [{"name": "主脾胃气虚", "desc": "右关候脾胃，脉来软弱无力，是脾胃气弱、鼓动不足之征。原文两段均见“右脉软弱”，且伴饮食不思、神昏足冷等症，说明中气已伤，运化无力，故软弱脉直接反映脾胃气虚。"}], "n": {"主脾胃气虚": 2}, "a": {"6248": "主脾胃气虚", "6541": "主脾胃气虚"}, "t": 2, "np": 0}, "c:急+平": {"o": "急平脉总属正虚邪留、邪正交争之象。其脉急而不甚数，或兼虚象，反映正气已亏而邪气未解，寒热错杂，腠理空疏。各段所论，或为阴暑正虚邪留，或为质虚加感、寒热复作，皆以正虚为本，邪郁为标。急脉主邪正交争，虚急并见则示元亏未复；弦急则邪郁未解，正气受亏。诸类之间，正虚邪留为总纲，邪正交争、寒热错杂、元亏腠疏为其具体表现，彼此关联，共同揭示急平脉所主病机以虚实夹杂、寒热失调为核心。", "c": [{"name": "主正虚邪留", "desc": "脉急而兼虚，或弦急见于汗出热退之后，为正虚邪恋之象。原文谓“脉见弦急，为邪郁未解、正气受亏之象”，又云“脉虚近急，虚为元亏未复，急为寒热愈而复作、邪正交争之象”，皆因正气亏虚，无力驱邪，邪郁不解，故脉急而虚。"}], "n": {"主正虚邪留": 2}, "a": {"15430": "主正虚邪留", "15449": "主正虚邪留"}, "t": 2, "np": 0}, "pc:寸+弦+急": {"o": "寸·弦急脉总属气机郁滞、脏腑失调之象，其病机涉及多个层面。弦为肝脉，急主气迫，寸部见之，首先反映上焦气郁与火邪为患，如右寸弦急主气郁胸中、肺失宣降；左右寸口弦劲则为火乘金，灼伤肺阴。其次，弦急见于关部，为肝木横逆、侮脾犯土，导致食少体瘦。再者，左尺虚数提示肾水不足，水不涵木，使肝阳偏亢，弦急难缓。四类病机相互关联：水亏为木旺之本，木旺则侮土、乘金，形成连锁反应。总以肝气偏亢、脏腑功能失调为核心，脉象未平即病本未除，提示病情缠绵，需从整体调治。", "c": [{"name": "主火乘金", "desc": "寸口脉弦劲，为火邪乘肺之象。原文谓『左右寸口脉仍弦劲，火乘金也』，弦急未减说明火势未平。火性急迫，灼伤肺金，故见咳呛、鼻衄、盗汗等症，脉象反映火盛金伤之病机。"}], "n": {"主火乘金": 2}, "a": {"15493": "主火乘金", "19311": "主火乘金"}, "t": 2, "np": 0}, "pc:右+虚+微": {"o": "右·虚微脉总属正虚之象，虚为不足，微为阳衰，合之则阴阳两亏、气血津液俱损。所主病机主要有三：一为阴阳两亏，多见于素体亏虚、误治伤正之危候；二为津液内亡，因热耗或误下致化源不足，脉道不充；三为寒邪内陷，正虚无力抗邪，寒邪深陷三阴。三者相互关联，总以虚为本，或兼寒陷，或兼津亡，皆因正气虚衰而脉见虚微。临床须结合兼脉及证候，辨其虚损之侧重与邪气之进退。", "c": [{"name": "主阴阳两亏", "desc": "右脉虚微，虚为不足，微为阳衰，合之则阴阳两亏。原文见泄精、溏泻后复感寒邪，误治致厥逆、神识模糊，脉证合参属阴阳两亏、邪难达表之危候。虚微脉直接反映正气虚衰，阴阳俱损。"}], "n": {"主阴阳两亏": 2}, "a": {"15614": "主阴阳两亏", "25090": "主阴阳两亏"}, "t": 2, "np": 0}, "c:急+促": {"o": "急促脉总属危候，其病机核心为正气衰败与邪热鸱张，并可导致血气败乱、上热下寒。正气衰败则阴阳将脱，脉数而迫促；邪热鸱张则逼迫脉道，亦见急促。血气败乱则脉急促如喘，发为暴厥不语；上热下寒、水火不交则脉亦急促，发为昏眩。四类病机相互关联：正气衰败为根本，邪热鸱张为标象，血气败乱与上热下寒为进一步演变，终致阴阳离决之危。", "c": [{"name": "主正气衰败", "desc": "脉急促为危候，急促者数而迫促，主正气衰败。如案中便泄数十次、恶露全无、腹膨鼻煽，脉急促示阴阳将脱，正气衰败，故为危候。"}], "n": {"主正气衰败": 2}, "a": {"15899": "主正气衰败", "23060": "主正气衰败"}, "t": 2, "np": 0}, "pc:关+细+虚": {"o": "关·细虚脉总属正虚之象，以气阴不足、脾胃虚弱为基本病机。虚细并见，虚为阳气不足，细为阴血亏少，合而示气血阴阳俱损，尤以气阴两虚为要。其病位多在肺、脾、胃，可因虚而招邪，形成本虚标实之候，如肝风烁肺、胃气虚热。此外，虚细脉为里气不实之征，凡见此类脉象，攻下发汗皆当审慎，误治则重虚其虚。诸类之间，气阴两虚为共同基础，肝风烁肺为虚中夹实之变，胃气虚热为虚而兼热之候，里虚禁下则示其治疗禁忌，总不离“正虚”二字。", "c": [{"name": "主气阴两虚", "desc": "关脉虚细，虚为不足，细为阴血亏少，合而示气阴两虚。原文见右寸关虚细，伴呛咳久累、舌心红、癸水异常，乃肺脾气阴耗损之象，故主气阴两虚。"}], "n": {"主气阴两虚": 2}, "a": {"16878": "主气阴两虚", "22934": "主气阴两虚"}, "t": 2, "np": 0}, "pc:尺+浮+缓": {"o": "尺·浮缓脉总起来主风邪外袭、湿痹、脾伤湿热及肾气受损。浮脉主风，缓脉主湿，风与湿合，痹阻气血，郁而化热，则见脾色外现而发黄；若兼趺阳紧数，则脾胃湿热内蕴，谷气不消，发为谷疸；尺脉本沉而浮，又提示肾气受损。诸类病机相互关联：风邪外袭为始动因素，湿痹为病理基础，脾伤湿热为关键环节，肾伤为病进之变，共同构成黄疸病表里寒热虚实交错的复杂病机。", "c": [{"name": "主风邪外袭", "desc": "原文“寸口脉浮而缓，浮则为风”“缓则伤风”，浮主风邪在表，缓为风性弛纵，故尺浮缓脉可反映风邪外袭之病机，风与湿合则发黄。"}], "n": {"主风邪外袭": 2}, "a": {"21416": "主风邪外袭", "24898": "主风邪外袭"}, "t": 2, "np": 0}, "pc:左+涩+和": {"o": "左·涩和脉总以涩脉为基点，主血行不畅与血少两类病机。涩脉往来艰涩，既可因瘀血内阻、脉络不通，亦可因血少脉道不充、往来滞涩。原文咳血而左脉涩，正是瘀阻与血少并存之象；治后涩象渐和，则示瘀化血行、血络渐通，故咳血止而咳势大减。可见涩脉所主，不离血分：瘀与虚常相互影响，瘀久伤血，血少滞涩，二者可转化并见。临证见涩，当辨其偏瘀偏虚，以瘀化、血充则脉渐和为期。", "c": [{"name": "主血瘀", "desc": "涩脉往来艰涩，如轻刀刮竹，主血行不畅。原文左脉涩，伴咳血，为瘀血阻络之象；涩象渐和则瘀滞渐化，血行渐畅，故咳血止、咳势减，说明涩脉可主血瘀。"}], "n": {"主血瘀": 1}, "a": {"12488": "主血瘀"}, "t": 1, "np": 0}, "c:和+硬": {"o": "硬和脉总起来主肝盛、脾伤、肺伤、阴虚阳亢及肝胆留邪等病机。弦为肝脉，肝盛则脉弦硬而不和缓；脉失和缓之脾土之气，是脾气受伤；肺金受伤不能镇肝，致肝木偏亢而脉弦。三者相互关联：肝盛侮脾，脾伤则土不培金，肺金亦伤；肺伤则金不制木，肝愈横。若真阴耗伤，不能涵木，则风阳内炽，脉见弦硬而舌赤无津，此阴虚阳亢之候。肝胆留邪，气机郁滞，亦令脉道弦硬。诸类之中，肝盛为始动，脾伤、肺伤为传变，阴虚阳亢为深重阶段，肝胆留邪为兼夹因素，总以肝木失和、脉失柔缓为共同特征。", "c": [{"name": "主肝盛", "desc": "弦为肝脉，肝气偏盛则脉道紧张而弦硬不和。原文脉至弦硬，患者素患肝气，胁腹时胀，显系肝木横逆、气机壅滞之象，故脉硬主肝盛气逆。"}], "n": {"主肝盛": 1}, "a": {"13124": "主肝盛"}, "t": 1, "np": 0}, "pc:左+洪+缓": {"o": "左·洪缓脉总起来主气虚、虚阳外浮及气血不足。洪缓无力非实热之洪，乃脾胃气虚、虚阳外越之象；左脉缓小而弱，为气血不足之征。患者形肥色淡紫，冬月感寒，前医发散伤阳，又用寒凉降下，致身热自汗、胸膈痞闷、便泻食少，右脉洪缓无力，左脉缓小而弱，皆气虚阳陷之候。洪缓无力与缓小弱并见，提示虚阳外浮而气血内亏，故三类病机相互关联：气虚为本，虚阳外浮为标，气血不足为兼，总属虚证，非实热可攻。", "c": [{"name": "主气虚", "desc": "洪缓无力为脾胃气虚、虚阳外浮之象。患者形肥色淡紫，冬月感寒，前医发散伤阳，又用寒凉降下，致身热自汗、便泻食少，右脉洪缓无力，左脉缓小而弱，皆气虚阳陷之征。"}], "n": {"主气虚": 1}, "a": {"15150": "主气虚"}, "t": 1, "np": 0}, "pc:右+滑+紧": {"o": "右·滑紧脉总属寒邪与食积交阻之候，以感寒夹食、大腹疼痛为典型病机。紧脉主寒邪收引，滑脉主食积痰滞，右脉候中焦脾胃，故脉象复合反映寒凝气滞、食积内停。三类病机中，‘主寒凝’为病机之基，寒邪收引则气机不畅；‘主食积’言食滞中焦之性；‘主寒食交阻’则概括二者相合为病。三者相互关联，共同揭示寒食交阻、气滞腹痛之病机本质。", "c": [{"name": "主寒凝", "desc": "紧脉主寒邪收引，寒性凝滞，使气血收引不畅。原文‘右脉紧滑’而见大腹疼痛，紧脉反映寒邪内侵、收引作痛，故主寒凝气滞之病机。"}], "n": {"主寒凝": 1}, "a": {"15511": "主寒凝"}, "t": 1, "np": 0}, "pc:关+虚+实": {"o": "关部虚实脉在此案中并非单一脉象，而是复合脉象的统称：关脉滑数主痰火实，寸尺软小濡小主气火虚，合而观之，总主虚实夹杂、痰火内壅兼气火不足之病机。其核心在于痰与火、气与虚的交互：气火虚则痰不易出，痰火实则气逆壅盛，二者互为因果。故临床见关滑数而寸尺无力者，当识为虚实夹杂之候，治宜标本兼顾，以治本为主、治标为辅。三类病机中，痰火实与气火虚为分述，虚实夹杂为总括，共同构成该脉所主病机的完整图景。", "c": [{"name": "主痰火实", "desc": "关脉滑数，为痰火内盛之象。原文谓‘滑数为痰火实’，痰火壅盛则气逆喘咳、痰不易出。滑主痰，数主火，火与痰互结，故关部滑数直接反映痰火实证。"}], "n": {"主痰火实": 1}, "a": {"15518": "主痰火实"}, "t": 1, "np": 0}, "pc:关+小+濡": {"o": "关·小濡脉总属虚象，主阴亏阳弱、气血不足，兼有虚火内郁。其脉形小濡，为脉道不充、鼓动无力之征，反映正气亏虚。从原文看，右脉细耎无力主脾肺气虚，左寸涩主心血不足，关弦数主肝火内郁，尺濡小主肾阴亏虚。四类病机相互关联：素体阴亏阳弱为本，脾肺气虚、心血不足为气血之虚，肾阴亏虚则水不养木，肝火内郁则相火上炎。总以虚损为主，虚中夹实，故见咳血颧红、痰沫常吐等虚怯之征。治疗上需兼顾扶脾保肺、滋阴降火，不可纯用滋阴而碍脾。", "c": [{"name": "主肾阴亏虚", "desc": "尺脉濡小，为肾阴亏虚之象。濡小者，脉形细软而小，阴精不足，脉道不充。原文谓“尺脉濡小为肾阴亏虚”，又见“素体阴亏阳弱”，故关脉小濡亦反映肾阴亏虚，水不养木，相火上炎。"}], "n": {"主肾阴亏虚": 1}, "a": {"15942": "主肾阴亏虚"}, "t": 1, "np": 0}, "pc:两+数+小": {"o": "两·数小脉总属阴虚内热、津伤化燥之候。小脉主营血不足，数脉主热，二者相合，多为阴血亏虚，虚热内生。原文见苔转微白、尖边尚红，呛咳音嘶，乃热灼肺津，金失濡润，故虑防涸阴。其病机核心为阴分不足，虚热扰灼，津液受损，甚则有涸竭之虞。两类病机相互关联：阴虚生内热，热灼更伤津，津伤又加重阴虚，形成恶性循环。治当顾护阴液，清热润燥，以防阴涸。", "c": [{"name": "主阴虚内热", "desc": "脉小数，小为阴血不足，数为热象。原文苔转微白、尖边尚红，示热势稍退而阴分未复；呛咳较减而音犹嘶，乃肺津受灼、金失濡润。脉症合参，显系阴血亏虚，虚热内扰。"}], "n": {"主阴虚内热": 1}, "a": {"17085": "主阴虚内热"}, "t": 1, "np": 0}, "pc:寸+滑+坚": {"o": "寸·滑坚脉总起来主痰浊胶固、结聚壅塞之病机。其脉滑为痰象，坚凝为痰结，见于寸关之间，提示顽痰结于肺胃之管。肺主清道，胃主浊道，痰结壅阻，气机不得宣降，故见喘咳、晕绝等症。此脉所主以痰结为核心，气壅为痰结所致之果，二者相互关联，共同构成痰浊胶固、壅塞气道的病机整体。原文特别指出，前医误作阴虚滋补，不知痰结为患，坚滑并见正是痰浊胶固之明证。", "c": [{"name": "主痰结", "desc": "原文谓“滑为痰象，坚凝为痰结”，寸关脉坚凝而滑，几乎搏指，是痰浊胶固、结聚于肺胃之管，壅塞清浊二道，故见喘咳晕绝，廿余年不愈。"}], "n": {"主痰结": 1}, "a": {"17230": "主痰结"}, "t": 1, "np": 0}, "pc:六+微+动": {"o": "微动脉总属气血暴脱之危候。其脉象微动无力、六脉不全，反映阴血骤失、气随血脱、脉道不充的核心病机。临床多见于大失血或久病耗伤，致气血将脱，出现精神昏愦、气息若无等症。此脉所主病机单一而危急，提示固脱止血为要。", "c": [{"name": "主气血暴脱", "desc": "脉微动无力，六脉不全，因阴血骤失，气随血脱，脉道不充。原文见行经下血不止、精神昏愦、气息若无，皆气血将脱之象，故微动脉主气血暴脱之危候。"}], "n": {"主气血暴脱": 1}, "a": {"19877": "主气血暴脱"}, "t": 1, "np": 0}, "pc:尺+大+坚": {"o": "尺·大坚脉总起来主正虚邪盛、重虚及阴竭阳浮三类病机，并关乎吉凶逆顺之判。其脉大主邪盛，急坚主正虚邪结，尺部候肾与下焦，故病位在里。原文以脉之浮大沉小判伤寒温病吉凶，强调正能抗邪则生，正虚邪盛则死；又论重虚，尺虚行步恇然，脉虚不象阴，滑生涩死；更指出阴竭阳浮者，脉见浮大沉小之变。诸类之间，邪盛与正虚常并见，阴竭阳浮为危重转归，而吉凶逆顺则贯穿于脉证相参之中，总以正邪胜负为枢机。", "c": [{"name": "主邪盛", "desc": "脉大主邪气盛实。原文以伤寒热盛脉浮大者生，因浮大示邪有外达之机；温病脉大疾者生，亦示正能抗邪。尺部大坚，说明邪实结于下焦或里，正气尚能抗邪，故主邪盛。"}], "n": {"主邪盛": 1}, "a": {"21824": "主邪盛"}, "t": 1, "np": 0}, "pc:右+浮+空": {"o": "右·浮空脉总属气虚，以浮为气浮、空为虚为纲。其病机核心是正气不足，尤以肺、脾、心、肝胆、肾诸脏气弱为具体表现，因六部脉虚各有所主。气虚则清阳不升，故主眩晕，并伴气短乏力。三类病机相互关联：气虚是根本，诸脏气弱是气虚在不同部位的体现，眩晕是气虚上荣不足的结果。脉浮而空，非实邪外浮，乃虚气外露之象，故辨证当以补气为要，不可误作表实。", "c": [{"name": "主气虚", "desc": "脉浮而空，浮为气浮于外，空为内虚不实，总属气虚。原文明言‘浮则为气，空则为虚’，且分述右寸肺气不足、右关中气不足、左寸心气不足、左关肝胆气弱、两尺肾气不足，诸部皆虚，故主气虚眩晕。"}], "n": {"主气虚": 1}, "a": {"24801": "主气虚"}, "t": 1, "np": 0}, "pc:关+浮+虚": {"o": "关·浮虚脉总起来主阴阳偏盛、气血郁滞、气虚及阴阳离决危候。其核心病机为阴阳失调：浮为气虚，虚而大则阴阳偏盛，气血留滞，甚则关格不通。原文引《素问》《灵枢》以人迎、寸口脉大四倍分格与关，并大曰关格，皆言脉而不言证，强调脉象反映阴阳偏盛之极；又引《难经》溢覆及阳脉不和、阴脉不和之说，说明阴阳偏盛可致气血郁滞。浮虚之象，虚为本，滞为标，若脉羸不能极天地之精则死，提示危候。各类之间，气虚为始，阴阳偏盛为枢，气血郁滞为果，危候为极，层层递进，总属阴阳失调、气血失和之病机。", "c": [{"name": "主阴阳偏盛", "desc": "脉浮虚而关部显著，反映阴阳偏盛。原文引《素问》《灵枢》谓人迎脉大四倍曰格，寸口脉大四倍曰关，并大曰关格，皆阴阳偏盛之象。浮为气虚，虚而大则阴阳不相协调，气血偏聚，故主阴阳偏盛、关格之病。"}], "n": {"主阴阳偏盛": 1}, "a": {"25973": "主阴阳偏盛"}, "t": 1, "np": 0}, "pe:寸+细": {"o": "寸·细脉总以‘虚’为纲，主气血阴阳亏虚、脉道不充。细为血少气衰之象，寸候心肺，故多责之心肺气血不足；在此基础上，因兼脉不同而衍生多类病机：细而数主阴虚火旺，细而涩主气滞血少，细而紧主正虚寒结，细而滑主痰湿内蕴，细而弦劲主虚阳浮越，细而微弱主胃气败绝。诸类之间以虚为本，或虚中夹实（气滞、痰湿、寒结），或虚而致逆（阳浮、火旺），甚则脏气衰亡。其病位涉及心肺、脾胃、肝肾，总属正气亏虚、阴阳失调之候，预后视兼脉与胃神存亡而定。", "c": [{"name": "主虚损", "desc": "寸脉细而无力，为脉道不充、正气亏虚之象。原文多见‘寸脉细’‘两寸脉俱细’‘细耎难寻’，断为肺气不足、中气虚、少阴之虚、脑髓已坏等，皆因气血阴阳亏虚不能充盈脉道，故细脉总主诸般虚损，甚则脏气败绝。"}, {"name": "主气滞", "desc": "细而兼涩或细滞，主气机壅滞、脉道不畅。原文‘寸脉依然细滞’‘左脉寸涩’，断为肝郁气结、气滞痰凝，由胠胁蔓及虚里，阻神明、乱魂魄；细为血少，涩滞为气不通，故细脉可兼主气滞。"}, {"name": "主痰湿", "desc": "细而兼滑，主痰湿内蕴。原文‘脉滑者，多血少气’‘沉细滑疾者热’，细为阴血不足，滑为痰湿壅盛，气机被遏；寸部候上焦心肺，故细滑脉主痰湿郁阻、痰热内蕴，兼见阴液受伤、气滞血少之复合病机。"}, {"name": "主阴虚火旺", "desc": "细而兼数，主阴液亏虚、虚热内生。原文‘数细’‘细数’多归阴虚火旺：左寸细数责心阳浮越或心血虚火旺，右寸细数主肺燥液干，右关细数主脾阴亏损，两尺细数主肾水枯竭。细为阴血津精不足，数为虚火躁动，故细数脉总主阴虚火旺。"}, {"name": "主胃气败绝", "desc": "寸脉细微而兼怪脉如屋漏、雀啄，或两寸细而关尺无神，主胃气败绝、脏气衰亡。原文‘细微脉兼见怪脉’‘两寸脉俱细，关尺皆已无神’断为绝证、脑已坏、胃气败绝，乃正气败绝、脉无胃神之危候，预后不良。"}], "n": {"主虚损": 5, "主气滞": 1, "主痰湿": 1, "主阴虚火旺": 1, "主胃气败绝": 1}, "a": {"7715": "主气滞", "11649": "主阴虚火旺", "12251": "主胃气败绝", "15650": "主虚损", "15942": "主虚损", "21803": "主痰湿", "21807": "主虚损", "24751": "主虚损", "25096": "主虚损"}, "t": 9, "np": 0}, "pe:寸+实": {"o": "寸·实脉总起来主邪实壅盛于上焦，以实热为核心，兼及痰食、火刑金、热壅上焦及虚实夹杂。实脉为邪气盛、脉道壅实之象，寸部候心肺与上焦，故实脉见于寸，多主上焦实热壅盛，非虚火可比。其具体病机可分五类：实热壅盛者，火热亢盛于上；痰食壅阻者，滑实并见，痰热食积壅于上中二焦；火热刑金者，实大洪数，胃火肺热刑克肺金；热壅上焦者，洪实而尺弱，上焦热盛兼下元不固；虚实夹杂者，寸脉软小而关滑数，气火虚与痰火实并见。诸类之间，实热壅盛为基础，痰食、火刑金、热壅上焦皆实热之变，虚实夹杂则为实中挟虚之特殊情形。总以邪实壅盛、热郁上焦为纲，虚实寒热之辨为要。", "c": [{"name": "主实热壅盛", "desc": "寸脉实而有力，为邪热亢盛之象。原文见两寸甚实而牙疼久不愈，用引血下行、清热之品而愈；又见右手三部微实、六脉俱数，为相火妄行、火热郁于肺脾。实主邪壅，数主热盛，寸候上焦，故主上焦实热壅盛，非虚火可比。"}, {"name": "主虚实夹杂", "desc": "寸·虚实脉主虚实夹杂之证。原文见右寸软小不疏、左尺濡小无力，主气火虚衰；关滑数，主痰火内实。虚者正气不足，实者痰火壅滞，二者互为因果，致喘咳有年、气逆痰壅难卧。气火虚为本，痰火实为标，虚实夹杂为病机关键。"}], "n": {"主实热壅盛": 2, "主虚实夹杂": 4}, "a": {"3917": "主虚实夹杂", "19932": "主实热壅盛", "21801": "主虚实夹杂", "21803": "主虚实夹杂", "21807": "主虚实夹杂", "23815": "主实热壅盛"}, "t": 6, "np": 0}, "pe:右+结": {"o": "右·结脉总起来主气机郁滞、脉道不利，其病机可归纳为气滞、饮结、积滞、痰阻及虚中夹实五类。结脉的基本特征是脉来迟缓而时有一止，主气结不续。从所收段落看，右结脉多与弦、伏、微、涩、促等脉并见，提示病性有实有虚，但以气机壅阻为核心。气滞则脉气不续，饮结支脉则气不流通，积滞内停则脉道不利，痰阻隧道则气血不畅，虚中夹实则气血结滞不通。各类之间相互关联：气滞可致饮结、痰阻，积滞可加重气机壅阻，久病则虚实夹杂。故右结脉所主以气机郁结为共同基础，具体病机则随兼脉及症候而异。", "c": [{"name": "主气滞", "desc": "结脉主气机郁滞、脉道不利。原文见右脉结而左脉弦，情怀抑郁，气勃于中，五志过极皆从火化，示肝郁气滞、火郁于内；又见弦硬间现结脉，为气分有亏、脉道不利。气滞则脉气不续，故结。"}, {"name": "主饮结", "desc": "结脉主饮邪结聚、支脉阻结。原文脉右弦，舌黄不渴，当心似阻，咳久不已，卧著则咳，痰出稍安，知清阳少旋、支脉结饮。饮结支脉则气不流通，卧则饮逆故咳，痰出饮减故稍安，结脉示饮结气阻。"}, {"name": "主虚中夹实", "desc": "结脉主气血郁滞、虚中夹实。右涩结脉以涩示血少行滞，以结示气滞血瘀、脉气不续，合而反映气血结滞不通；若兼弦小，又见肝郁脾弱、木郁土衰之象。原文论噎膈因七情内伤致五脏空虚、气无所主，食不能进，故脉涩结。"}], "n": {"主气滞": 1, "主饮结": 1, "主虚中夹实": 1}, "a": {"1371": "主饮结", "12532": "主气滞", "20378": "主虚中夹实"}, "t": 3, "np": 0}, "pe:关+结": {"o": "关结脉总起来主气机郁闭、积滞内停、湿热瘀结及本虚标实之病机。其基本特征为脉气结塞、关窍不通，故凡气血瘀阻、湿热蕴结、食积气滞、惊气入脏等致脉道不利者，皆可见结。各类之间以“结塞不通”为共同基础：湿热瘀结侧重血分瘀热，气机郁闭侧重气分壅塞，肝郁肾衰属虚中夹实，食积气滞则关涉脾胃运化。诸类或独立为病，或相兼为患，总不离关脉所主之脾胃肝胆及气血郁结之机。", "c": [{"name": "主湿热瘀结", "desc": "关结脉主湿热蕴结、气血瘀阻。原文“血脉关结”指血行瘀滞、关窍结塞，脉结反映气血瘀阻；通草、木通苦泄通利，善治湿热蕴结不通，故脉结与湿热瘀结、九窍不利相应。"}], "n": {"主湿热瘀结": 2}, "a": {"26965": "主湿热瘀结", "26966": "主湿热瘀结"}, "t": 2, "np": 0}, "ps:右关+洪": {"o": "右关洪脉总主痰热、实积、火盛、瘀血及邪盛诸病机。洪为热盛之象，滑主痰湿，数主火，大主邪盛，涩主瘀血。右关候脾胃，故洪滑多主中焦痰热壅盛、实积内结；兼数则火邪亢盛，兼涩则痰瘀互结；洪大有力则示邪气盛实、热势下迫。诸类之间以痰热为核心，实积、火盛、瘀血、邪盛皆可由此衍生或兼夹，总属实证、热证范畴，反映邪热痰浊壅滞中焦、流注他处之病机。", "c": [{"name": "主痰热", "desc": "右关洪滑多主痰热壅盛中焦。原文如‘洪滑主痰热’，‘右关洪滑主痰热壅滞中焦’，‘右关洪滑主痰浊壅盛于中’，‘洪滑主胃中痰热’，‘洪滑主痰热实积’，均以洪滑并见为痰热内蕴之征。"}, {"name": "主实积", "desc": "洪滑有力主实热积滞内结。如‘洪滑主痰热实积’，‘右关洪滑、两尺有力，主中焦痰热积滞’，‘脉洪滑数大，说明痰热内蕴’，均示洪滑有力为实邪壅盛、积滞内结之象。"}, {"name": "主火盛", "desc": "洪数之脉主火邪亢盛。如‘左寸洪数，数主火’，‘左寸洪数乃心火亢盛’，‘左寸洪数主心火亢盛’，‘左寸洪数主心火’，均以洪数并见为火热内盛、心火亢盛之征。"}], "n": {"主痰热": 6, "主实积": 2, "主火盛": 1}, "a": {"4027": "主痰热", "4328": "主痰热", "6014": "主痰热", "6023": "主痰热", "6133": "主实积", "6308": "主痰热", "6317": "主痰热", "6428": "主实积", "18419": "主火盛"}, "t": 9, "np": 0}, "rc:沉取+数+细": {"o": "沉取数细脉总以细数为基础，细主阴血不足或脉道不利，数主热，然其病机有虚实寒热之辨。虚证方面，或为阴亏内热，或为阳气虚馁、虚阳上攻，或为正虚邪陷，甚则阴寒内盛、虚阳外越之真寒假热。实证方面，或为郁热化毒，或为食积湿热内结，或为热厥里实。其鉴别关键在于重按之力：重按无力、无神者多虚，重按滑、长、有力者多实。各类之间以“细数”为共同脉象，因兼脉及按诊不同而分属不同病机，临证须结合症候，勿执一而论。", "c": [{"name": "主阴亏内热", "desc": "脉细数无神，或细数而重按无力，多因素体阴亏，虚热内生。原文如案149“素体阴亏，肝阳向盛”，脉“细数无神”，细主阴血不足，数主内热，故主阴亏火旺之虚损证。"}, {"name": "主虚阳上攻", "desc": "脉细数而右更细软，重按即无，为阳气虚馁，虚阳上浮。如丁汉奇案“六脉细数，右手尤细软，略一重按即无”，细数为阴虚有热，濡软为阳虚，合之则虚阳上攻，非实热。"}, {"name": "主正虚邪陷", "desc": "脉细数不耐重按，伴面色㿠白、正元素乏，为正气不足，邪热内郁，不得外达。原文“六脉细数不耐重按”“正元素乏”，细为元正不足，数为邪热内郁，重按无力示虚象显著，主正虚邪陷之机。"}, {"name": "主真寒假热", "desc": "脉细数而重取不见，外见满面通红、躁扰冷饮等热象，为阴寒内盛，虚阳外越之真寒假热证。原文“六脉细数，重取不见”，细为阴亏，数为虚热，重按无力为根本虚衰，故主阴极似阳。"}, {"name": "主郁热化毒", "desc": "脉细而兼数，见于乳房肿痛、寒热交作，为肝胃郁热，乳络壅塞，郁蒸化毒。原文“细主阴血不足，数主热郁化毒”，肝失畅达，胃乏冲和，营气不从，胶固不宣，故脉细数主郁热成毒。"}, {"name": "主食积湿热", "desc": "脉细数俨似阴虚，然重按滑而有力，为食积中宫，脉道不利，湿热内蕴。原文“重按则滑而有力”，滑为食积，有力为实，细乃食结所致，非虚细，故主食积湿热内结之实证。"}, {"name": "主热厥里实", "desc": "脉细数而重按则长，伴干呕烦热、手足时冷、齿燥舌黄，为邪热内郁，热深厥深。原文“脉虽细，重按则长”，细为热郁于里，数为邪热，长为实象，故主热厥里实，非胃寒。"}, {"name": "其他", "desc": "无法归入上述类别的段落"}], "n": {"主阴亏内热": 1, "主虚阳上攻": 2, "主正虚邪陷": 2, "主真寒假热": 1, "主郁热化毒": 1, "主食积湿热": 1, "主热厥里实": 1, "其他": 0}, "a": {"2020": "主正虚邪陷", "3388": "主虚阳上攻", "4174": "主虚阳上攻", "7484": "主阴亏内热", "11083": "主正虚邪陷", "12069": "主真寒假热", "12311": "主郁热化毒", "16115": "主食积湿热", "16147": "主热厥里实"}, "t": 9, "np": 0}, "rc:沉取+数+浮": {"o": "沉取·数浮脉总属虚阳外浮、阴不敛阳之象。其脉浮数，浮为阳浮于外，数为热，然沉取必无力、甚空或如无，故非实热。所主病机可分三类：一为阴虚阳浮，阴亏不能潜阳，虚热外浮；二为热盛阴竭，邪热炽盛而阴液将竭，脉虽浮数有力而重按甚空；三为虚阳外越，元气大虚，虚阳浮越，脉浮数重按如无。三者皆以正虚为本，或阴虚，或津耗，或元虚，热象为标。其共同特征为浮数之脉沉取无力，提示虚火浮越，治当滋阴潜阳、清热救阴或温补元气，不可误作实热而妄投苦寒。", "c": [{"name": "主阴虚阳浮", "desc": "脉浮数而重按无力，为阴分亏损、不能潜阳，虚阳外浮而作热。如段20208失血过多，阴不敛阳则发热喘逆；段4924体属阴虚，伏寒化热，津液暗耗，脉数如浮重按无力，皆属此类。"}, {"name": "主热盛阴竭", "desc": "脉浮数有力而重按甚空，为阳明热极、阴分将竭之象。如段19758温病误治，热渴喘促，头汗自出，脉浮数有力重按甚空，热盛于外而阴液内竭，脉体不实。"}, {"name": "主虚阳外越", "desc": "脉浮数而重按如无，为元气大虚、虚阳外浮，数亦虚火。如段23993腰疽服寒凉败毒，色黯不痛，气粗短促，脉浮数重按如无，乃寒药伤阳、元气欲脱之候。"}, {"name": "其他", "desc": "无法归入上述类别的段落"}], "n": {"主阴虚阳浮": 2, "主热盛阴竭": 1, "主虚阳外越": 1, "其他": 0}, "a": {"4924": "主阴虚阳浮", "19758": "主热盛阴竭", "20208": "主阴虚阳浮", "23993": "主虚阳外越"}, "t": 4, "np": 0}, "rs:浮取+动": {"o": "浮取·动脉总起来主虚风内动、痰瘀互结、气机逆乱、水饮内停等病机。其脉象特征为举之有余、按之不足，或机神荡动、按之似滑、举之和缓，或按之有力、举之似涩。这些病机多与中焦脾胃相关，虚风内动因阳气不藏，痰瘀互结因邪实内结，气机逆乱因升降失常，水饮内停因痰饮搏结。各类之间相互关联，虚风、痰瘀、水饮均可导致气机逆乱，而气机逆乱又加重痰瘀水饮的形成，形成恶性循环。总以中焦气机失调为核心，虚实夹杂，故脉见动脉之象。", "c": [{"name": "主虚风内动", "desc": "脉机神荡动，举之和缓，按之似滑，为胃气尚存而虚风内动之象。阳气不藏，故见巨阙下微痛、腹间动气。动气在中脘建里间，乃中焦气机逆乱，水饮与虚风相搏，主病在脾胃。"}, {"name": "主痰瘀互结", "desc": "脉按之有力，举之似涩，为实中夹瘀之象。有力主邪实内结，涩主气滞血瘀，故腹间建里有块碌碌而响，期门不容水分俱有动气，独中脘建里最甚。动气聚于中焦，块响不散，乃痰瘀互结、气机壅塞。"}, {"name": "主气机逆乱", "desc": "脉六部机神荡动，按之似滑，举之和缓，腹间动气在中脘建里间，为阳气不藏、中焦气机逆乱之象。滑为痰饮内停，缓为胃气未绝，动气聚于中焦，水饮与虚风相搏，气机升降失常。"}, {"name": "主水饮内停", "desc": "脉按之似滑，举之和缓，滑为痰饮内停之征。腹间动气少许，在中脘建里间，乃水饮与虚风相搏，中焦气机逆乱。动气者，水饮停聚，气机不畅，故脉见滑而机神荡动。"}, {"name": "其他", "desc": "无法归入上述类别的段落"}], "n": {"主虚风内动": 1, "主痰瘀互结": 1, "主气机逆乱": 0, "主水饮内停": 0, "其他": 0}, "a": {"2936": "主虚风内动", "2937": "主痰瘀互结", "21797": "__np", "25786": "__np"}, "t": 4, "np": 2}});